INSERT OR IGNORE INTO text_profiles(
    entity_id,text_type,original_language_id,attributed_author,compiler,composition_period,earliest_extant_witness,chapter_structure,repository,shelfmark,copyright_status,summary
) VALUES
('text.egypt.bentresh_stela','NARRATIVE_INSCRIPTION','lang.egy',NULL,NULL,'Late Period or Ptolemaic (disputed)','Stela found in 1829 near the Khonsu temple at Karnak, now Louvre C 284',NULL,'Musée du Louvre','C 284','Ancient text in the public domain','A princess of Bakhtan, sister of Ramesses II''s queen, is possessed by a spirit; Khonsu-the-Provider travels from Thebes, expels it, and returns after a dream of a golden falcon.'),
('text.egypt.two_brothers','NARRATIVE','lang.egy',NULL,NULL,'Nineteenth Dynasty','Papyrus D''Orbiney, copied by the scribe Ennana',NULL,'The British Museum','EA 10183','Ancient text in the public domain','Two brothers, a false accusation, a heart hidden on a pine, and Bata''s rebirths as bull, persea tree and king.'),
('text.egypt.hatshepsut_birth_cycle','RELIEF_CYCLE','lang.egy',NULL,NULL,'Reign of Hatshepsut','Reliefs and captions of the middle colonnade, north side, Deir el-Bahari',NULL,'In situ, Deir el-Bahari',NULL,'Ancient text in the public domain','Council of the gods, union of Amun and Ahmose, Khnum at the wheel, annunciation, birth, presentation and nursing of the divine child.'),
('text.ugaritic.baal_cycle.ktu1_3_1_4','MYTHIC_EPIC','lang.uga',NULL,NULL,'Late Bronze Age, Ugarit','Clay tablets from Ras Shamra (Ugarit)','Six columns per tablet, partly broken',NULL,NULL,'Ancient text in the public domain','Baal''s feast, Anat''s battle, the plea for a house, Athirat''s visit to El, the building of the palace and the window.'),
('text.sumerian.inana_ebih','NARRATIVE_HYMN','lang.sux',NULL,NULL,'Composed in the late third or early second millennium BCE; Old Babylonian copies','Old Babylonian tablets, including one from Ur',NULL,NULL,NULL,'Ancient text in the public domain','Hymn to Inana''s terror; her complaint against Ebiḫ; her plea to An; An''s warning; the destruction of the mountain; her victory speech.');

