INSERT OR IGNORE INTO claims(
    id,subject_id,predicate,object_entity_id,object_literal,object_datatype,statement,variant_group,claim_status,confidence,confidence_level,review_status,assertion_scope,knowledge_layer,tradition_scope,temporal_scope,research_notes,created_at
) VALUES
('claim.v0360.hym_apollo.01','deity.greek.leto','NARRATIVE_ACTION',NULL,'unstrings Apollo''s bow and rejoices in her children','string','Homeric Hymn 3, lines 1–18, says that when Apollo enters Zeus''s house the gods rise, and Leto alone stays seated, takes his bow and rejoices in having borne Apollo and Artemis, she in Ortygia and he in Delos.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.02','deity.greek.leto','NARRATIVE_ACTION',NULL,'wanders from land to land seeking a birthplace for Apollo','string','Homeric Hymn 3, lines 19–50, lists the many lands Leto visited while in labour with Apollo and says that none dared to receive him until she came to Delos.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.03','deity.greek.leto','NARRATIVE_ACTION','site.greece.delos',NULL,NULL,'Homeric Hymn 3, lines 51–88, says that Delos agreed to receive Leto only after she swore by Earth, Heaven and the water of Styx that Apollo''s altar and precinct would be there and that he would honour the island above all.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.04','deity.greek.hera','NARRATIVE_ACTION','deity.greek.eileithyia',NULL,NULL,'Homeric Hymn 3, lines 89–114, says that Leto laboured nine days and nights because jealous Hera kept Eileithyia on Olympus, until the goddesses sent Iris with the promise of a nine-cubit golden necklace to bring her.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.05','deity.greek.leto','NARRATIVE_ACTION','deity.greek.apollo',NULL,NULL,'Homeric Hymn 3, lines 115–126, says that Leto, clasping a palm tree and kneeling on the meadow, bore Apollo, whom the goddesses washed and swaddled and Themis fed with nectar and ambrosia.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.06','deity.greek.apollo','NARRATIVE_ACTION',NULL,'claims the lyre, the bow and the declaring of Zeus''s will','string','Homeric Hymn 3, lines 127–139, says that the newborn Apollo, after tasting ambrosia, burst his swaddling bands and claimed the lyre and the curved bow and the declaring of Zeus''s will, and that Delos was laden with gold.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.07','deity.greek.apollo','NARRATIVE_ACTION','site.greece.delos',NULL,NULL,'Homeric Hymn 3, lines 140–178, describes the Ionian festival for Apollo on Delos, the Delian maidens who sing of Apollo, Leto and Artemis, and the poet''s request to be remembered as the blind man of Chios.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.08','deity.greek.artemis','NARRATIVE_ACTION',NULL,'sings among the dancing goddesses on Olympus','string','Homeric Hymn 3, lines 179–206, says that when Apollo came to Olympus playing his lyre, the Muses sang, the Graces, Hours, Harmonia, Hebe and Aphrodite danced, and Artemis, Apollo''s twin, sang among them while Leto and Zeus rejoiced.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.09','deity.greek.apollo','NARRATIVE_ACTION',NULL,'is turned away from Telphusa''s spring toward Crisa','string','Homeric Hymn 3, lines 207–276, says that Apollo travelled from Pieria through Euboea and Boeotia seeking a site for his oracle, and that the spring nymph Telphusa, jealous of her glory, persuaded him to go instead to Crisa below Parnassus.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.10','deity.greek.apollo','NARRATIVE_ACTION','site.greece.delphi',NULL,NULL,'Homeric Hymn 3, lines 277–304, says that Apollo laid the foundations of his temple at Crisa below Parnassus, that Trophonius and Agamedes laid its stone threshold, and that a fierce she-dragon who had reared Typhaon for Hera lived by a nearby spring.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.11','creature.greek.typhon','ORIGIN',NULL,'born of Hera alone, without Zeus, and given to the she-dragon to rear','string','Homeric Hymn 3, lines 305–355, says that Hera, angered that Zeus had borne Athena alone, prayed to Earth, Heaven and the Titans, kept away from Zeus for a year, bore Typhaon without him and gave him to the she-dragon to rear.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.12','deity.greek.apollo','KILLED','creature.greek.delphic_drakaina',NULL,NULL,'Homeric Hymn 3, lines 356–387, says that Apollo shot the she-dragon, that her body rotted (pythein) in the sun so that the place is called Pytho, and that he then buried Telphusa''s spring beneath a crag.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.13','deity.greek.apollo','ASSUMES_FORM',NULL,'a dolphin that steers a Cretan ship to Crisa','string','Homeric Hymn 3, lines 388–439, says that Apollo, seeking priests for his temple, leapt onto a Cretan ship from Cnossos in the form of a dolphin and carried it, against the will of its crew, around the Peloponnese to Crisa.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_apollo.14','deity.greek.apollo','NARRATIVE_ACTION',NULL,'makes the Cretan sailors keepers of his temple at Pytho','string','Homeric Hymn 3, lines 440–546, says that Apollo revealed himself to the Cretans at Crisa, made them keepers of his temple, named his altar Delphinius after the dolphin, led them to Pytho singing the paean and warned them against insolence.','v0360.hym_apollo','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.01','deity.greek.maia','NARRATIVE_ACTION','deity.greek.zeus',NULL,NULL,'Homeric Hymn 4, lines 1–19, says that the shy nymph Maia, living in a shadowy cave, was visited by Zeus at night while Hera slept, and bore Hermes, who was born at dawn, played the lyre at midday and stole Apollo''s cattle in the evening.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.02','deity.greek.hermes','CREATOR_OF',NULL,'the first lyre, made from a tortoise shell','string','Homeric Hymn 4, lines 20–61, says that the newborn Hermes found a tortoise at the mouth of Maia''s cave, made a seven-stringed lyre from its shell and sang of Zeus and Maia.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.03','deity.greek.hermes','NARRATIVE_ACTION',NULL,'steals fifty cows and drives them backwards','string','Homeric Hymn 4, lines 62–86, says that at sunset Hermes went to Pieria, took fifty of the gods'' cattle, drove them backwards to confuse their tracks and wove sandals of tamarisk and myrtle twigs to hide his own.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.04','deity.greek.hermes','NARRATIVE_ACTION',NULL,'warns the old man at Onchestus to keep silent','string','Homeric Hymn 4, lines 87–104, says that Hermes told an old man working his vineyard at Onchestus to keep silent about what he had seen, and drove Apollo''s cattle through the night to a byre by the river Alpheus.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.05','deity.greek.hermes','NARRATIVE_ACTION',NULL,'first makes fire with fire-sticks and divides the meat into twelve portions','string','Homeric Hymn 4, lines 105–141, says that Hermes, the first to make fire with fire-sticks, slaughtered two of the cows by the Alpheus, divided the roasted meat into twelve portions without eating it, and destroyed the traces of the feast.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.06','deity.greek.maia','NARRATIVE_ACTION','deity.greek.hermes',NULL,NULL,'Homeric Hymn 4, lines 142–183, says that Hermes slipped back into Maia''s cave through the keyhole like mist and lay in his cradle, and that Maia rebuked him, while he answered that he would win honour like Apollo''s or become prince of robbers.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.07','deity.greek.apollo','NARRATIVE_ACTION',NULL,'follows the backward tracks of his stolen cattle','string','Homeric Hymn 4, lines 184–212, says that Apollo, seeking his fifty cattle, questioned the old man at Onchestus, knew the thief from a bird omen, and marvelled at the backward cattle tracks and the strange footprints beside them.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.08','deity.greek.apollo','NARRATIVE_ACTION','deity.greek.maia',NULL,NULL,'Homeric Hymn 4, lines 213–277, says that Apollo came to Maia''s cave on Cyllene, searched its storerooms full of nectar, ambrosia, gold, silver and the nymph''s garments, and threatened Hermes, who lay curled in his cradle and denied all knowledge of the cattle.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.09','deity.greek.hermes','NARRATIVE_ACTION',NULL,'demands that Zeus judge the quarrel over the cattle','string','Homeric Hymn 4, lines 278–322, says that Apollo laughed at Hermes and named him prince of robbers, that Hermes, when lifted, sent forth an omen and sneezed, and that the two agreed to take their quarrel to Zeus.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.10','deity.greek.zeus','NARRATIVE_ACTION','deity.greek.hermes',NULL,NULL,'Homeric Hymn 4, lines 323–396, says that Apollo accused Hermes before Zeus, that Hermes denied the theft with clever oaths, and that Zeus laughed and ordered the brothers to search together, with Hermes showing where the cattle were hidden.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.11','deity.greek.hermes','GAVE_AWAY',NULL,'gives the lyre to Apollo in exchange for the cattle','string','Homeric Hymn 4, lines 397–502, says that when Apollo tried to bind Hermes the withies took root around the cattle, and that Hermes enchanted Apollo with the lyre and gave it to him in exchange for the cattle and the herdsman''s whip.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_hermes.12','deity.greek.apollo','NARRATIVE_ACTION','deity.greek.hermes',NULL,NULL,'Homeric Hymn 4, lines 503–580, says that Hermes swore by Styx never to steal from Apollo, that Apollo gave him a golden staff of wealth and told him of the three bee-maidens of Parnassus, and that Zeus made Hermes lord of beasts and messenger to Hades.','v0360.hym_hermes','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.01','deity.greek.aphrodite','NARRATIVE_ACTION','deity.greek.athena',NULL,NULL,'Homeric Hymn 5, lines 1–15, says that Aphrodite subdues gods, men, birds and beasts, but cannot bend Athena, who delights in war and in crafts and first taught craftsmen to make chariots and maidens to do handiwork.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.02','deity.greek.artemis','NARRATIVE_ACTION',NULL,'is never tamed in love by Aphrodite','string','Homeric Hymn 5, lines 16–20, says that Aphrodite can never tame Artemis, who loves archery, hunting in the mountains, the lyre and dance, shady woods and the cities of upright men.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.03','deity.greek.hestia','NARRATIVE_ACTION',NULL,'swears by Zeus''s head to remain a maiden and receives the hearth''s honour','string','Homeric Hymn 5, lines 21–32, says that Hestia, first and youngest child of Cronos, refused Poseidon and Apollo and swore by Zeus''s head to remain a maiden, and that Zeus gave her the centre of every house and honour in all temples.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.04','deity.greek.zeus','NARRATIVE_ACTION','deity.greek.aphrodite',NULL,NULL,'Homeric Hymn 5, lines 33–55, says that Aphrodite deceives even Zeus into loving mortal women and boasts of it, so Zeus put into her heart desire for the mortal Anchises, who was herding cattle on Ida.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.05','deity.greek.aphrodite','NARRATIVE_ACTION',NULL,'is adorned at Paphos and crosses Ida among the wild beasts','string','Homeric Hymn 5, lines 56–74, says that Aphrodite was bathed and anointed by the Graces in her temple at Paphos, then flew to Mount Ida, where wolves, lions, bears and leopards fawned on her and she put desire in their hearts.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.06','hero.greek.anchises','NARRATIVE_ACTION','deity.greek.aphrodite',NULL,NULL,'Homeric Hymn 5, lines 75–106, says that Aphrodite appeared to Anchises alone at his hut on Ida in the form of an unwed maiden, and that he took her for a goddess and promised her an altar in return for prosperity and long life.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.07','deity.greek.aphrodite','NARRATIVE_ACTION',NULL,'claims to be a daughter of King Otreus of Phrygia','string','Homeric Hymn 5, lines 107–142, says that Aphrodite told Anchises she was a mortal, daughter of King Otreus of Phrygia, raised by a Trojan nurse, and carried off by Hermes from the dance of Artemis to be his wife.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.08','hero.greek.anchises','NARRATIVE_ACTION','deity.greek.aphrodite',NULL,NULL,'Homeric Hymn 5, lines 143–167, says that Anchises, believing Aphrodite mortal, took her to his couch spread with the skins of bears and lions, so that by the will of the gods a mortal lay with a goddess unknowing.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.09','hero.greek.anchises','NARRATIVE_ACTION',NULL,'hides his face and begs the goddess not to leave him enfeebled','string','Homeric Hymn 5, lines 168–190, says that Aphrodite, revealed in her divine stature and beauty, woke Anchises, who hid his face in fear and begged her not to leave him enfeebled for having lain with a goddess.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.10','deity.greek.aphrodite','NARRATIVE_ACTION','hero.greek.aeneas',NULL,NULL,'Homeric Hymn 5, lines 191–217, says that Aphrodite foretold to Anchises a son named Aeneas who would reign among the Trojans, and told how Zeus carried off Ganymede to pour wine for the gods and consoled his father Tros with immortal horses.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.11','deity.greek.eos','NARRATIVE_ACTION','hero.greek.tithonus',NULL,NULL,'Homeric Hymn 5, lines 218–238, says that Eos asked Zeus to make Tithonus immortal but forgot to ask for unageing youth, so that when old age overwhelmed him she shut him in a chamber where his voice flows on endlessly.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hym_aphrodite.12','deity.greek.aphrodite','NARRATIVE_ACTION',NULL,'entrusts Aeneas to the nymphs of Ida and warns Anchises to keep silent','string','Homeric Hymn 5, lines 239–293, says that Aphrodite lamented her shame among the gods, entrusted the child to the long-lived mountain nymphs of Ida whose lives are bound to trees, and warned Anchises that Zeus would strike him if he boasted of her.','v0360.hym_aphrodite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymns (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.01','deity.greek.erebus','CHILD_OF','deity.greek.chaos',NULL,NULL,'Hesiod, Theogony 116–123, says that after Chaos, Earth, Tartarus and Eros came to be, Erebus and black Night came forth from Chaos.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.02','deity.greek.aether','SIBLING_OF','deity.greek.hemera',NULL,NULL,'Hesiod, Theogony 124–125, says that Night conceived in union with Erebus and bore Aether and Hemera (Day).','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.03','deity.greek.crius','SIBLING_OF','deity.greek.theia',NULL,NULL,'Hesiod, Theogony 126–138, says that Earth bore Heaven, the mountains and Pontus, and then to Heaven bore the Titans, among them Coeus, Crius, Hyperion, Iapetus, Theia, Rhea, Themis, Mnemosyne, Phoebe, Tethys and, youngest, Cronos.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.04','deity.greek.hypnos','SIBLING_OF','deity.greek.thanatos',NULL,NULL,'Hesiod, Theogony 211–225, says that Night, without union with any god, bore Doom, Fate and Death (Thanatos), and Sleep (Hypnos) with the tribe of Dreams, together with Blame, Woe, the Hesperides, the Fates, Nemesis, Deceit, Friendship, Old Age and Strife.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.05','deity.greek.eurybia','CHILD_OF','deity.greek.pontus',NULL,NULL,'Hesiod, Theogony 233–239, says that Sea begot Nereus and, in union with Earth, Thaumas, Phorcys, Ceto and Eurybia, who has a heart of flint within her.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.06','deity.greek.selene','CHILD_OF','deity.greek.hyperion',NULL,NULL,'Hesiod, Theogony 371–374, says that Theia, in love with Hyperion, bore great Helios, clear Selene and Eos, who shines on all on earth and on the deathless gods.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.07','deity.greek.astraeus','CHILD_OF','deity.greek.crius',NULL,NULL,'Hesiod, Theogony 375–377, says that Eurybia, in love with Crius, bore great Astraeus, Pallas and Perses, eminent among all in wisdom.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.08','deity.greek.eos','CONSORT_OF','deity.greek.astraeus',NULL,NULL,'Hesiod, Theogony 378–382, says that Eos bore to Astraeus the winds Zephyrus, Boreas and Notus, and then the morning star Eosphorus and the gleaming stars.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.09','deity.greek.pallas_titan','CONSORT_OF','deity.greek.styx',NULL,NULL,'Hesiod, Theogony 383–388, says that Styx, daughter of Ocean, bore to Pallas Zelos, Nike, Kratos and Bia, who never leave Zeus but dwell always with him.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.10','deity.greek.styx','NARRATIVE_ACTION','deity.greek.zeus',NULL,NULL,'Hesiod, Theogony 389–403, says that when Zeus summoned the gods against the Titans, Styx came first to Olympus with her children on Ocean''s advice, and Zeus made her the great oath of the gods and her children his constant companions.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.11','deity.greek.asteria','CONSORT_OF','deity.greek.perses',NULL,NULL,'Hesiod, Theogony 404–411, says that Phoebe bore to Coeus gentle Leto and Asteria of happy name, whom Perses led to his great house to be his dear wife.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.12','deity.greek.hecate','CHILD_OF','deity.greek.perses',NULL,NULL,'Hesiod, Theogony 411–452, says that Asteria bore Hecate to Perses, and that Zeus honoured her above all, giving her a share in earth, sea and heaven and power to aid kings, warriors, athletes, fishermen and herdsmen.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.13','deity.greek.hemera','NARRATIVE_ACTION','deity.greek.nyx',NULL,NULL,'Hesiod, Theogony 744–757, says that near where Atlas holds up heaven, Night and Day greet each other as they pass the great bronze threshold, one going in as the other goes out, so that the house never holds both, Day bringing light to men and Night carrying Sleep.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.14','deity.greek.thanatos','DWELLS_IN',NULL,'a dwelling at the edge of the world, never seen by the sun','string','Hesiod, Theogony 758–766, says that Sleep and Death, children of Night, dwell where the sun never looks on them, Sleep roaming gently and kindly over earth and sea, Death having a heart of iron and holding fast whomever he seizes.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.theog_titans.15','deity.greek.eos','CONSORT_OF','hero.greek.tithonus',NULL,NULL,'Hesiod, Theogony 984–991, says that Eos bore to Tithonus Memnon, king of the Ethiopians, and Emathion, and to Cephalus Phaethon, whom Aphrodite carried off to keep her shrine by night.','v0360.theog_titans','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.01','deity.greek.artemis','CHILD_OF','deity.greek.leto',NULL,NULL,'Apollodorus, Library 1.4.1, says that Leto, hunted by Hera, came to Delos and bore Artemis first, with whose help as midwife she then bore Apollo, and that Artemis devoted herself to the chase and remained a maiden.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.02','deity.greek.artemis','NARRATIVE_ACTION',NULL,'shoots down Tityus with Apollo to protect Leto','string','Apollodorus, Library 1.4.1, says that when the earth-born giant Tityus tried to seize Leto at Pytho, she called her children, and Artemis and Apollo shot him down; vultures eat his heart in Hades.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.03','deity.greek.artemis','KILLED','hero.greek.orion',NULL,NULL,'Apollodorus, Library 1.4.3–1.4.5, says that Artemis slew the giant hunter Orion in Delos after Eos had carried him there, either for challenging her at quoits or for assaulting the Hyperborean maiden Opis.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.04','deity.greek.artemis','NARRATIVE_ACTION',NULL,'kills the Aloadae on Naxos by leaping between them as a deer','string','Apollodorus, Library 1.7.4, says that the giant Aloadae piled Ossa on Olympus and Pelion on Ossa, wooed Hera and Artemis and bound Ares, and that Artemis killed them in Naxos by turning into a deer so that they speared each other.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.05','deity.greek.artemis','NARRATIVE_ACTION',NULL,'sends the Calydonian boar when Oeneus forgets her first-fruits','string','Apollodorus, Library 1.8.2, says that when Oeneus of Calydon offered first-fruits to all the gods but forgot Artemis, she sent a huge boar that ravaged the land, which Meleager and the assembled heroes, with Atalanta, hunted down.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.06','deity.greek.artemis','NARRATIVE_ACTION',NULL,'fills Admetus''s bridal chamber with coiled snakes','string','Apollodorus, Library 1.9.15, says that Admetus forgot to sacrifice to Artemis at his marriage to Alcestis and found his bridal chamber full of coiled snakes, so that Apollo bade him appease the goddess.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.07','deity.greek.artemis','NARRATIVE_ACTION','hero.greek.heracles',NULL,NULL,'Apollodorus, Library 2.5.3, says that when Heracles shot the golden-horned Ceryneian hind sacred to Artemis, Artemis and Apollo met him and Artemis rebuked him, until he appeased her by laying the blame on Eurystheus.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.08','deity.greek.artemis','TRANSFORMS_INTO','hero.greek.actaeon',NULL,NULL,'Apollodorus, Library 3.4.4, says that Actaeon, according to the commoner account, saw Artemis bathing, and that she turned him into a deer and maddened his fifty hounds, which devoured him on Cithaeron.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.09','deity.greek.artemis','NARRATIVE_ACTION','hero.greek.niobe',NULL,NULL,'Apollodorus, Library 3.5.6, says that when Niobe boasted she was more blessed in children than Leto, Leto stirred up her twins, Artemis shot down Niobe''s daughters in the house and Apollo her sons on Cithaeron, and Niobe was turned to weeping stone at Sipylus.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.10','deity.greek.artemis','KILLED','hero.greek.callisto',NULL,NULL,'Apollodorus, Library 3.8.2, says that Artemis shot down her companion Callisto, whom Zeus had turned into a bear, either at Hera''s persuasion or because she had not kept her maidenhood, and that Zeus gave her son Arcas to Maia to rear and set Callisto among the stars as the Bear.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.11','deity.greek.artemis','NARRATIVE_ACTION',NULL,'holds the Greek fleet at Aulis without wind','string','Apollodorus, Epitome 3.21, says that the Greek fleet at Aulis could not sail for want of wind because Artemis was angry with Agamemnon, who had boasted after shooting a deer and whose father Atreus had withheld the golden lamb, so that Calchas demanded the sacrifice of his fairest daughter.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_artemis.12','deity.greek.artemis','NARRATIVE_ACTION','hero.greek.iphigenia',NULL,NULL,'Apollodorus, Epitome 3.22, says that as Agamemnon was about to sacrifice Iphigenia at the altar, Artemis snatched her away to the Taurians to be her priestess and put a deer in her place, or, as some say, made her immortal.','v0360.lib_artemis','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.01','deity.greek.semele','NARRATIVE_ACTION','deity.greek.zeus',NULL,NULL,'Apollodorus, Library 3.4.2–3.4.3, says that Zeus loved Semele, daughter of Cadmus, and that, deceived by Hera, she asked Zeus, who had promised her anything, to come to her as he had come when he wooed Hera.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.02','deity.greek.semele','NARRATIVE_ACTION',NULL,'dies of fright when Zeus comes in thunder and lightning','string','Apollodorus, Library 3.4.3, says that Zeus came to Semele''s chamber in a chariot with lightning and thunder and launched a thunderbolt, that Semele died of fright, and that Zeus snatched the six-month child from the fire and sewed it in his thigh.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.03','deity.greek.dionysus','CHILD_OF','deity.greek.zeus',NULL,NULL,'Apollodorus, Library 3.4.3, says that Semele''s sisters spread the report that she had lain with a mortal, and that Zeus at the proper time undid the stitches, gave birth to Dionysus and entrusted him to Hermes, who took him to Ino and Athamas to be reared as a girl.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.04','deity.greek.hera','NARRATIVE_ACTION',NULL,'drives Ino and Athamas mad for rearing Dionysus','string','Apollodorus, Library 3.4.3, says that Hera drove Ino and Athamas mad for rearing Dionysus, so that Athamas killed Learchus as a deer and Ino leapt into the sea with Melicertes, becoming Leucothea while the boy became Palaemon.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.05','deity.greek.dionysus','TRANSFORMS_INTO',NULL,'a kid, carried by Hermes to the nymphs of Nysa','string','Apollodorus, Library 3.4.3, says that Zeus turned Dionysus into a kid to escape Hera and that Hermes took him to the nymphs at Nysa in Asia, whom Zeus later turned into the stars called the Hyades.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.06','deity.greek.dionysus','NARRATIVE_ACTION','deity.greek.rhea',NULL,NULL,'Apollodorus, Library 3.5.1, says that Dionysus discovered the vine, was driven mad by Hera and roamed Egypt and Syria, was received by Proteus, and at Cybela in Phrygia was purified by Rhea and learned the rites of initiation.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.07','deity.greek.dionysus','NARRATIVE_ACTION','person.greek.lycurgus_edonian',NULL,NULL,'Apollodorus, Library 3.5.1, says that Lycurgus, king of the Edonians, insulted and expelled Dionysus, who fled into the sea to Thetis, and that Dionysus drove Lycurgus mad so that he killed his own son, and the Edonians had him destroyed by horses on Mount Pangaeum.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.08','deity.greek.dionysus','NARRATIVE_ACTION',NULL,'drives the women of Thebes to rave on Cithaeron','string','Apollodorus, Library 3.5.2, says that Dionysus, having passed through Thrace and India and set up pillars, came to Thebes and forced the women to leave their homes and rave on Cithaeron, and that Pentheus, son of Agave and Echion, tried to stop the rites.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.09','deity.greek.dionysus','NARRATIVE_ACTION','hero.greek.pentheus',NULL,NULL,'Apollodorus, Library 3.5.2, says that Pentheus, spying on the Bacchic women on Cithaeron, was torn limb from limb by his mother Agave in her frenzy, and that Dionysus, having shown the Thebans he was a god, then drove the women of Argos mad.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.10','deity.greek.dionysus','NARRATIVE_ACTION',NULL,'turns the pirates'' mast and oars into snakes','string','Apollodorus, Library 3.5.3, says that Tyrrhenian pirates hired to carry Dionysus from Icaria to Naxos tried to sell him in Asia, and that he turned the mast and oars into snakes and filled the ship with ivy and flutes, so that the pirates went mad, leapt into the sea and became dolphins.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.11','deity.greek.semele','NARRATIVE_ACTION',NULL,'is brought up from Hades by Dionysus and named Thyone','string','Apollodorus, Library 3.5.3, says that Dionysus, now honoured as a god, brought his mother up from Hades, named her Thyone and ascended with her to heaven.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.lib_dionysus.12','person.greek.icarius_attica','NARRATIVE_ACTION','deity.greek.dionysus',NULL,NULL,'Apollodorus, Library 3.14.7, says that Dionysus, coming to Attica in Pandion''s reign, was received by Icarius and taught him to make wine, and that shepherds who drank it unmixed thought themselves bewitched and killed him, after which his daughter Erigone hanged herself.','v0360.lib_dionysus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.01','deity.greek.ares','NARRATIVE_ACTION','deity.greek.athena',NULL,NULL,'Homer, Iliad 5.29–36, says that Athena took Ares by the hand, persuaded him to withdraw from the fighting to avoid Zeus''s anger, and seated him on the banks of the Scamander, after which the Achaeans drove the Trojans back.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.02','deity.greek.ares','NARRATIVE_ACTION','deity.greek.aphrodite',NULL,NULL,'Homer, Iliad 5.355–363, says that Aphrodite, wounded by Diomedes, found Ares sitting on the left of the battle and begged him to lend her his horses, which carried her to Olympus.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.03','deity.greek.ares','NARRATIVE_ACTION',NULL,'is kept bound in a bronze jar for thirteen months by the sons of Aloeus','string','Homer, Iliad 5.385–391, has Dione tell how Otus and Ephialtes, sons of Aloeus, bound Ares and kept him in a bronze jar for thirteen months until Hermes, told by Eëriboea, stole him away exhausted.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.04','deity.greek.ares','NARRATIVE_ACTION','deity.greek.apollo',NULL,NULL,'Homer, Iliad 5.454–470, says that Apollo called on Ares to drive Diomedes from the field, and that Ares, in the likeness of the Thracian leader Acamas, went among the Trojans and urged on the sons of Priam.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.05','deity.greek.ares','NARRATIVE_ACTION','hero.greek.diomedes',NULL,NULL,'Homer, Iliad 5.590–606, says that Ares and Enyo led the Trojans with Hector, Ares wielding a huge spear now before and now behind him, and that Diomedes, recognising the god, told his men to give ground facing the enemy.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.06','deity.greek.ares','NARRATIVE_ACTION',NULL,'slays Achaeans beside Hector as the Achaeans give ground','string','Homer, Iliad 5.699–710, says that the Achaeans gave ground on learning that Ares was among the Trojans, and names Teuthras, Orestes, Trechus, Oenomaus, Helenus and Oresbius as those slain by Hector and Ares.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.07','deity.greek.hera','NARRATIVE_ACTION','deity.greek.ares',NULL,NULL,'Homer, Iliad 5.711–792, says that Hera and Athena armed and drove from Olympus, that Hera asked Zeus whether he was not angry at Ares'' violence, and that Zeus told her to set Athena upon Ares, who most of all brings him pain.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.08','deity.greek.ares','NARRATIVE_ACTION',NULL,'is wounded in the belly by Diomedes'' spear, guided by Athena','string','Homer, Iliad 5.825–863, says that Athena, invisible in the cap of Hades, drove Diomedes'' chariot against Ares, turned aside Ares'' spear and drove Diomedes'' spear into his belly, so that he bellowed like nine or ten thousand men and rose to heaven like a dark cloud.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.09','deity.greek.zeus','NARRATIVE_ACTION','deity.greek.ares',NULL,NULL,'Homer, Iliad 5.864–909, says that the wounded Ares complained to Zeus about Athena, that Zeus called him the most hateful of the gods, who loves only strife and has Hera''s unyielding temper, yet had Paeon heal him, after which Hebe bathed him and he sat by Zeus.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.10','deity.greek.ares','NARRATIVE_ACTION',NULL,'is stopped by Athena from avenging his son Ascalaphus','string','Homer, Iliad 13.518–525 and 15.110–142, says that Ares'' son Ascalaphus was killed by Deiphobus while Ares sat unknowing on Olympus, and that when Hera told him, Ares resolved to avenge his son until Athena stripped his helmet, shield and spear and made him sit down.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.11','deity.greek.ares','NARRATIVE_ACTION',NULL,'shouts like a dark storm for the Trojans when the gods join battle','string','Homer, Iliad 20.31–74, says that when Zeus let the gods join the battle, Ares went to the Trojan side with Apollo, Artemis, Leto, Xanthus and Aphrodite, shouted like a dark storm from the citadel and Callicolone, and was matched against Athena.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.12','deity.greek.athena','STRUCK','deity.greek.ares',NULL,NULL,'Homer, Iliad 21.391–414, says that Ares attacked Athena and struck her aegis, and that Athena felled him with a great boundary stone, so that he covered seven plethra as he lay, while she mocked him with his mother Hera''s curses.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.iliad_ares.13','deity.greek.aphrodite','NARRATIVE_ACTION','deity.greek.ares',NULL,NULL,'Homer, Iliad 21.415–433, says that Aphrodite led the groaning Ares away from the battle, and that Athena, urged on by Hera, struck Aphrodite down with her hand so that both gods lay on the earth.','v0360.iliad_ares','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homer, Iliad (Butler translation)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.01','concept.norse.fire_ice_cosmogony','DESCRIBED_AS',NULL,'Niflheimr and the spring Hvergelmir, made long before the earth','string','Snorri''s Edda, Gylfaginning 4, says that before the earth was made there was Niflheimr, in whose midst lies the spring Hvergelmir from which many rivers flow, Gjöll running next to the gates of Hel.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.02','creature.norse.surtr','DWELLS_IN',NULL,'the border of Muspell, which he guards with a flaming sword','string','Snorri''s Edda, Gylfaginning 4, says that first there was the bright, burning southern world Muspell, at whose border sits Surtr with a flaming sword, who at the end of the world will defeat the gods and burn the world.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.03','concept.norse.fire_ice_cosmogony','DESCRIBED_AS',NULL,'rime from Niflheimr meeting sparks from Muspell in Ginnungagap','string','Snorri''s Edda, Gylfaginning 5, says that the poison of the rivers Élivágar froze into ice and rime that filled the northern part of Ginnungagap, while sparks from Muspell lit the southern part, and that where the warm air met the rime it melted and dripped.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.04','being.norse.ymir','ORIGIN',NULL,'formed from melting rime quickened by heat','string','Snorri''s Edda, Gylfaginning 5, says that the dripping rime quickened by heat took the shape of the giant Ymir, called Aurgelmir by the frost-giants, from whose sweat and legs the race of frost-giants came, and that he was not a god but evil.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.05','deity.norse.buri','ORIGIN','creature.norse.audhumla',NULL,NULL,'Snorri''s Edda, Gylfaginning 6, says that the cow Auðumbla, who fed Ymir with four rivers of milk, licked the salty ice-blocks until on the third day a whole man, Búri, beautiful, big and powerful, came out of them.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.06','deity.norse.borr','CONSORT_OF','being.norse.bestla',NULL,NULL,'Snorri''s Edda, Gylfaginning 6, says that Búri''s son Borr married Bestla, daughter of the giant Bölþorn, and that their sons were Óðinn, Vili and Vé, who must be the rulers of heaven and earth.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.07','being.norse.ymir','NARRATIVE_ACTION',NULL,'is killed by the sons of Borr, his blood drowning all the frost-giants but Bergelmir','string','Snorri''s Edda, Gylfaginning 7, says that the sons of Borr killed Ymir and that his blood drowned all the frost-giants except Bergelmir, who survived with his wife on his lúðr and from whom the frost-giants descend.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.08','event.norse.slaying_of_ymir','RESULTED_IN',NULL,'earth from Ymir''s flesh and the encircling sea from his blood','string','Snorri''s Edda, Gylfaginning 8, says that the sons of Borr carried Ymir to the middle of Ginnungagap and made the earth from his flesh, the sea and lakes from his blood and rocks and stones from his bones and teeth, setting the sea in a ring around the earth.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.09','being.norse.ymir','USED_AS',NULL,'the sky from Ymir''s skull and the stars from Muspell''s sparks','string','Snorri''s Edda, Gylfaginning 8, says that the sons of Borr made the sky from Ymir''s skull, set four dwarves, Austri, Vestri, Norðri and Suðri, under its corners, and fixed sparks from Muspell in the sky as lights, ordaining their courses.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.10','being.norse.ymir','USED_AS',NULL,'Miðgarðr, walled with Ymir''s eyelashes against the giants','string','Snorri''s Edda, Gylfaginning 8, says that the earth is round and ringed by the sea, that the gods gave the coasts to the giants and built Miðgarðr inland from Ymir''s eyelashes as a defence against them, and made the clouds from his brains.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.11','deity.norse.jord','NARRATIVE_ACTION','deity.norse.thor',NULL,NULL,'Snorri''s Edda, Gylfaginning 9, says that the sons of Borr made Askr and Embla from two logs, built Ásgarðr in the middle of the world, and that Jörð (Earth) was Óðinn''s daughter and wife, from whom he had his first son, Ása-Þórr.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.12','deity.norse.jord','CHILD_OF',NULL,'daughter of Nótt (Night) and Annarr','string','Snorri''s Edda, Gylfaginning 10, says that Nótt, daughter of the giant Narfi, bore Auðr to Naglfari, Jörð to Annarr and Dagr to Dellingr, and that Allfather set Night and Day in the sky with the horses Hrímfaxi and Skinfaxi.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.13','concept.norse.fire_ice_cosmogony','DESCRIBED_AS',NULL,'Sól and Máni, children of Mundilfari, set to drive the sun and moon','string','Snorri''s Edda, Gylfaginning 11, says that the gods, angered by Mundilfari''s arrogance in naming his children Máni and Sól, set them in the sky, Sól driving the sun''s horses Árvakr and Alsviðr and Máni steering the moon with the children Bil and Hjúki.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.gylf_creation.14','concept.norse.fire_ice_cosmogony','DESCRIBED_AS',NULL,'the wolves Sköll and Hati that pursue the sun and moon','string','Snorri''s Edda, Gylfaginning 12, says that the sun runs fast because the wolf Sköll pursues her and Hati Hróðvitnisson runs ahead to catch the moon, both born of an old giantess in Járnviðr, whose mightiest offspring Mánagarmr will swallow the moon.','v0360.gylf_creation','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.01','deity.norse.ullr','CHILD_OF','deity.norse.sif',NULL,NULL,'Snorri''s Edda, Gylfaginning 31, says that Ullr is the son of Sif and stepson of Thor, an unrivalled archer and skier, handsome and warlike, good to pray to in single combat.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.02','deity.norse.loki','NARRATIVE_ACTION','deity.norse.sif',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that gold is called Sif''s hair because Loki, out of mischief, cut off all of Sif''s hair.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.03','deity.norse.thor','NARRATIVE_ACTION','deity.norse.loki',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that when Thor caught Loki he would have broken every bone in him, until Loki swore to get the black elves to make Sif hair of gold that would grow like other hair.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.04','being.norse.sons_of_ivaldi','CREATOR_OF','artifact.norse.skidbladnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that the dwarves called the sons of Ívaldi made Sif''s golden hair, the ship Skíðblaðnir and the spear Gungnir.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.05','deity.norse.loki','NARRATIVE_ACTION','being.norse.brokkr',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that Loki wagered his head with the dwarf Brokkr that Brokkr''s brother Eitri could not make three treasures as good as those of the sons of Ívaldi.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.06','being.norse.eitri','CREATOR_OF','creature.norse.gullinbursti',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that Eitri laid a pigskin in the forge, and that although a fly stung Brokkr''s hand he kept blowing the bellows until Eitri took out a boar with golden bristles.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.07','being.norse.eitri','CREATOR_OF','artifact.norse.draupnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that Eitri next laid gold in the forge, and that although the fly stung Brokkr''s neck twice as hard he kept blowing until Eitri took out the gold ring Draupnir.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.08','being.norse.brokkr','NARRATIVE_ACTION','weapon.norse.mjolnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that when Eitri forged iron the fly stung Brokkr between the eyes so that he paused to brush it away, and that the hammer Eitri took out came near to being spoiled, its handle being rather short.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.09','deity.norse.odin','NARRATIVE_ACTION',NULL,'sits in judgement over the dwarves'' treasures with Thor and Freyr','string','Snorri''s Edda, Skáldskaparmál 35, says that when Brokkr and Loki brought their treasures to Ásgarðr the gods sat in judgement and agreed that the verdict of Óðinn, Thor and Freyr should stand.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.10','deity.norse.sif','RECEIVES',NULL,'golden hair that grows on her head like natural hair','string','Snorri''s Edda, Skáldskaparmál 35, says that Loki gave Óðinn the spear Gungnir, Freyr the ship Skíðblaðnir and Thor the golden hair for Sif, which as soon as it was placed on her head would grow like natural hair.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.11','weapon.norse.mjolnir','DESCRIBED_AS',NULL,'judged the best treasure, a defence against the frost-giants','string','Snorri''s Edda, Skáldskaparmál 35, says that Brokkr gave Óðinn the ring Draupnir, Freyr the shining boar and Thor the hammer that never misses and returns to his hand, and that the gods judged the hammer best as a defence against the frost-giants, so the dwarf won the wager.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_sif.12','being.norse.brokkr','NARRATIVE_ACTION','deity.norse.loki',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 35, says that when Loki argued that the dwarf had won his head but not his neck, Brokkr pierced Loki''s lips with his brother''s awl and sewed them with the thong Vartari, and that this is why gold is called Sif''s hair.','v0360.skald_sif','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.01','deity.norse.odin','NARRATIVE_ACTION','giant.norse.hrungnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that while Thor was in the east Óðinn rode Sleipnir to the giant Hrungnir, wagered his head that no horse in Jötunheimr was as good, and was chased by Hrungnir on Gullfaxi right into Ásgarðr.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.02','giant.norse.hrungnir','DRINKS',NULL,'drains Thor''s drinking bowls in the hall of the Æsir','string','Snorri''s Edda, Skáldskaparmál 17, says that when Hrungnir rode into Ásgarðr the Æsir invited him in to drink, and that he drained the bowls Thor usually drank from.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.03','giant.norse.hrungnir','NARRATIVE_ACTION','deity.norse.sif',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that the drunken Hrungnir boasted that he would carry Valhalla to Jötunheimr, sink Ásgarðr and kill all the gods except Freyja and Sif, whom he would take home, and that Freyja alone dared pour for him.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.04','deity.norse.thor','NARRATIVE_ACTION','giant.norse.hrungnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that when the gods called on Thor he came into the hall with his hammer raised, and that Hrungnir, unarmed and under Óðinn''s protection, challenged him to single combat at Grjótúnagarðar, the first challenge Thor had ever received.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.05','giant.norse.mokkurkalfi','ORIGIN',NULL,'made of clay by the giants, with a mare''s heart','string','Snorri''s Edda, Skáldskaparmál 17, says that the giants, fearing what would follow if Hrungnir died, made a clay giant at Grjótúnagarðar, nine leagues tall and three broad under the arms, called Mökkurkálfi, and gave him a mare''s heart.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.06','giant.norse.hrungnir','DESCRIBED_AS',NULL,'a three-cornered heart of stone, a stone head and a stone shield','string','Snorri''s Edda, Skáldskaparmál 17, says that Hrungnir''s heart was of hard stone and three-cornered, his head and shield of stone, and his weapon a whetstone, and that the clay giant Mökkurkálfi beside him was terrified when he saw Thor.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.07','hero.norse.thjalfi','NARRATIVE_ACTION','giant.norse.hrungnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that Thjálfi ran ahead and told Hrungnir that Thor would attack from under the ground, so that Hrungnir put his stone shield under his feet and stood on it, holding his whetstone in both hands.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.08','deity.norse.thor','KILLED','giant.norse.hrungnir',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that Thor''s hammer and Hrungnir''s whetstone met in the air, that one piece of the whetstone, from which whetstone rocks come, fell to earth and the other struck Thor''s head, and that Mjölnir shattered Hrungnir''s skull so that he fell with his leg across Thor''s neck.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.09','hero.norse.thjalfi','DEFEATED','giant.norse.mokkurkalfi',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that Thjálfi attacked the clay giant Mökkurkálfi, who fell with little glory.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.10','deity.norse.magni','NARRATIVE_ACTION','deity.norse.thor',NULL,NULL,'Snorri''s Edda, Skáldskaparmál 17, says that when neither Thjálfi nor all the Æsir could lift Hrungnir''s leg from Thor''s neck, Magni, Thor''s three-year-old son by the giantess Járnsaxa, threw it off, and Thor gave him the horse Gullfaxi, though Óðinn said it was wrong to give it to a giantess''s son.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.11','deity.norse.thor','HEALED',NULL,'is chanted over by the seeress Gróa to loosen the whetstone in his head','string','Snorri''s Edda, Skáldskaparmál 17, says that Thor went home to Þrúðvangar with the whetstone in his head, and that the seeress Gróa, wife of Aurvandill the Bold, chanted spells over him until it began to work loose.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.skald_hrungnir.12','deity.norse.thor','NARRATIVE_ACTION',NULL,'keeps the whetstone in his head when Gróa forgets her spells','string','Snorri''s Edda, Skáldskaparmál 17, says that Thor told Gróa he had carried Aurvandill out of Jötunheimr in a basket and made his frozen toe into a star, that Gróa in her joy forgot her spells, and that the whetstone stayed in Thor''s head, so that whetstones must not be thrown across the floor.','v0360.skald_hrungnir','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.01','historical.egyptian.ramesses_ii','NARRATIVE_ACTION',NULL,'receives tribute and the eldest daughter of the prince of Bakhtan in Naharin','string','The Bentresh Stela (Louvre C 284) opens with the titulary of Ramesses II and says that, receiving tribute in Naharin as each year, he was presented by the prince of Bakhtan with his eldest daughter at the head of the tribute.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.02','historical.egyptian.ramesses_ii','NARRATIVE_ACTION',NULL,'makes the princess of Bakhtan his Great Royal Wife Neferure','string','The Bentresh Stela (Louvre C 284) says that Ramesses II took the princess of Bakhtan as his wife, naming her Great Royal Wife Neferure, and that in Egypt she did all that a queen does.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.03','person.egyptian.bentresh','NARRATIVE_ACTION','festival.egyptian.opet',NULL,NULL,'The Bentresh Stela (Louvre C 284) says that in year 23, while Ramesses II was celebrating the Feast of Southern Ipet for Amun-Re at Thebes, a messenger of the prince of Bakhtan came to report that Bentresh, younger sister of Queen Neferure, was ill and to ask for a man of knowledge.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.04','person.egyptian.bentresh','NARRATIVE_ACTION',NULL,'is found possessed by a spirit that the scribe Djehutyemheb cannot overcome','string','The Bentresh Stela (Louvre C 284) says that Ramesses II sent the royal scribe Djehutyemheb from the House of Life to Bakhtan, and that he found Bentresh possessed by a spirit he could not overcome.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.05','historical.egyptian.ramesses_ii','NARRATIVE_ACTION',NULL,'is asked by the prince of Bakhtan to send a god against the spirit','string','The Bentresh Stela (Louvre C 284) says that in year 26 the prince of Bakhtan sent a second messenger asking Ramesses II to send a god to fight the spirit possessing Bentresh.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.06','deity.egyptian.khonsu','NARRATIVE_ACTION',NULL,'Khonsu-in-Thebes-Neferhotep gives his protection fourfold to Khonsu-the-Provider','string','The Bentresh Stela (Louvre C 284) says that Ramesses II asked Khonsu-in-Thebes-Neferhotep to send Khonsu-the-Provider, who expels disease demons, to Bakhtan, and that the god nodded and gave his protection fourfold to Khonsu-the-Provider.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.07','deity.egyptian.khonsu','NARRATIVE_ACTION',NULL,'travels a year and five months to Bakhtan in a great bark','string','The Bentresh Stela (Louvre C 284) says that Khonsu-the-Provider was sent in a great bark with an escort of five boats, chariots and horses and reached Bakhtan after a year and five months, where the prince and his officials prostrated themselves before him.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.08','deity.egyptian.khonsu','HEALED','person.egyptian.bentresh',NULL,NULL,'The Bentresh Stela (Louvre C 284) says that Khonsu-the-Provider went to the place where Bentresh was, made his protection over her, and she was well at once.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.09','deity.egyptian.khonsu','NARRATIVE_ACTION',NULL,'grants the departing spirit a feast with the prince of Bakhtan','string','The Bentresh Stela (Louvre C 284) says that the spirit possessing Bentresh welcomed Khonsu-the-Provider, called itself his servant, promised to go back whence it came and asked for a feast with the prince of Bakhtan, and that the god bade the prince make a great offering before it.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.10','deity.egyptian.khonsu','NARRATIVE_ACTION',NULL,'sends the spirit away in peace after the feast','string','The Bentresh Stela (Louvre C 284) says that the prince of Bakhtan, standing in fear, made a great offering and held a feast for Khonsu-the-Provider and the spirit, after which the spirit departed in peace at the god''s command and all Bakhtan rejoiced.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.11','deity.egyptian.khonsu','ASSUMES_FORM',NULL,'a falcon of gold flying from his shrine toward Egypt','string','The Bentresh Stela (Louvre C 284) says that the prince of Bakhtan kept the god for three years and nine months, until he dreamed of the god coming out of his shrine as a golden falcon and flying toward Egypt, and then resolved to send him home.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.bentresh.12','deity.egyptian.khonsu','NARRATIVE_ACTION',NULL,'lays all of Bakhtan''s gifts before Khonsu-in-Thebes-Neferhotep','string','The Bentresh Stela (Louvre C 284) says that the prince of Bakhtan sent the god back with many gifts, soldiers and horses, and that Khonsu-the-Provider, arriving at Thebes in year 33, laid all the gifts before Khonsu-in-Thebes-Neferhotep and kept nothing for his own house.','v0360.bentresh','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Bentresh Stela (Louvre C 284)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.01','hero.egyptian.bata','SIBLING_OF','hero.egyptian.anpu',NULL,NULL,'Papyrus D''Orbiney (the Tale of Two Brothers) begins by saying that Anubis and Bata were brothers of one mother and one father, that Bata lived with the married Anubis like a son and did all the work of the fields, and that the strength of a god was in him.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.02','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'herds cattle that tell him where the grass is good','string','Papyrus D''Orbiney says that Bata tended his brother''s cattle, slept among them in the stable, and that the cattle told him where the good grass was, so that they multiplied greatly.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.03','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'refuses his brother''s wife, calling her like a mother to him','string','Papyrus D''Orbiney says that when Bata came home for seed, his elder brother''s wife, admiring his strength, propositioned him, and that he refused in anger, calling her like a mother and his brother like a father, and promised to tell no one.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.04','hero.egyptian.anpu','NARRATIVE_ACTION',NULL,'is told by his wife that Bata assaulted her','string','Papyrus D''Orbiney says that the elder brother''s wife made herself appear beaten and told Anubis that Bata had tried to seduce her and beaten her, urging him to kill Bata.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.05','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'is warned by his cows and flees from his brother''s spear','string','Papyrus D''Orbiney says that Anubis waited behind the stable door with a spear to kill Bata, that the lead cow and the next cow warned Bata, who saw his brother''s feet under the door and fled.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.06','deity.egyptian.ra_horakhty','NARRATIVE_ACTION','hero.egyptian.bata',NULL,NULL,'Papyrus D''Orbiney says that Bata, fleeing, prayed to Pre-Harakhti as the judge of the wrongdoer and the just, and that Re made a great water full of crocodiles appear between the brothers.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.07','hero.egyptian.bata','NARRATIVE_ACTION','hero.egyptian.anpu',NULL,NULL,'Papyrus D''Orbiney says that at dawn Bata told his elder brother the truth across the water, swore by Pre-Harakhti, and in proof maimed himself, throwing the flesh into the water where a catfish swallowed it, while Anubis wept, unable to cross.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.08','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'places his heart on the flower of the pine in the Valley of the Pine','string','Papyrus D''Orbiney says that Bata went to the Valley of the Pine and placed his heart on top of the pine''s flower, telling Anubis to seek it if the pine were cut and to know of his danger when his beer fermented, and that Anubis went home, killed his wife and mourned his brother.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.09','deity.egyptian.ra_horakhty','NARRATIVE_ACTION','deity.egyptian.khnum',NULL,NULL,'Papyrus D''Orbiney says that the Ennead, meeting Bata alone in the Valley of the Pine, pitied him, and that Pre-Harakhti told Khnum to fashion a wife for Bata, whom the Seven Hathors foretold would die by the knife.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.10','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'tells his wife the secret that his heart is on the pine','string','Papyrus D''Orbiney says that Bata told his wife the secret of his heart and warned her not to go out, that the Sea pursued her and the pine took a lock of her hair, and that the Sea carried the scented lock to Pharaoh''s launderers in Egypt.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.11','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'kills Pharaoh''s first envoys but loses his wife to the second embassy','string','Papyrus D''Orbiney says that Pharaoh''s scribes declared the lock to belong to a daughter of Pre-Harakhti, that Bata killed the envoys sent to the Valley of the Pine but one, and that a second embassy with soldiers and a woman bearing jewels brought Bata''s wife to Pharaoh, who made her Great Noble Lady.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.12','hero.egyptian.bata','NARRATIVE_ACTION',NULL,'falls dead when the flower holding his heart is cut','string','Papyrus D''Orbiney says that Bata''s wife told Pharaoh to have the pine felled, and that when the soldiers cut the flower on which his heart lay Bata fell dead.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.13','hero.egyptian.anpu','NARRATIVE_ACTION','hero.egyptian.bata',NULL,NULL,'Papyrus D''Orbiney says that when Anubis''s beer fermented he went to the Valley of the Pine, found Bata dead, searched three years for his heart, found it as a fruit in the fourth year, and revived Bata by placing it in a bowl of cool water for him to drink.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.14','hero.egyptian.bata','TRANSFORMS_INTO',NULL,'a great bull of every beautiful colour','string','Papyrus D''Orbiney says that the revived Bata became a bull of every beautiful colour, was brought by Anubis to Pharaoh, revealed himself to his wife in the kitchen, and that she made Pharaoh swear to let her eat the bull''s liver.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.two_brothers.15','hero.egyptian.bata','NARRATIVE_ACTION','hero.egyptian.anpu',NULL,NULL,'Papyrus D''Orbiney says that two drops of the bull''s blood grew into persea trees, that a splinter from them flew into the Lady''s mouth so that she conceived and bore Bata as Pharaoh''s son, and that Bata became king, judged his wife, made Anubis crown prince and reigned thirty years before Anubis succeeded him.','v0360.two_brothers','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Tale of Two Brothers (Papyrus D''Orbiney)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.01','deity.egyptian.amun_ra','NARRATIVE_ACTION',NULL,'announces before the gods that he will beget a future ruler','string','The divine birth cycle of Hatshepsut at Deir el-Bahari opens with Amun-Re enthroned before the assembled gods, announcing his intention to beget a future ruler of the Two Lands.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.02','deity.egyptian.amun','NARRATIVE_ACTION','deity.egyptian.thoth',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Amun conferring with Thoth, who tells him of Ahmose, queen of Thutmose I, as the woman to bear his child.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.03','deity.egyptian.thoth','NARRATIVE_ACTION','deity.egyptian.amun',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Thoth leading Amun to the palace of Queen Ahmose.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.04','deity.egyptian.amun_ra','NARRATIVE_ACTION','historical.egyptian.ahmose_queen',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Amun, in the form of Thutmose I, coming to Queen Ahmose, who wakes at his fragrance and sees him in his divine form, and Amun naming the daughter he has placed in her body Khenemet-Amun Hatshepsut.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.05','deity.egyptian.amun','NARRATIVE_ACTION','deity.egyptian.khnum',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Amun commanding Khnum to fashion his daughter and her ka, to be greater than all the gods and king of the Two Lands.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.06','deity.egyptian.khnum','CREATOR_OF','historical.egyptian.hatshepsut',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Khnum shaping Hatshepsut and her ka on the potter''s wheel while Heqet holds out the sign of life, and Khnum promising her life, health, all lands and appearance on the throne of Horus for ever.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.07','deity.egyptian.thoth','NARRATIVE_ACTION','historical.egyptian.ahmose_queen',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Thoth coming before Queen Ahmose to announce her dignity and the coming birth, declaring that Amun is satisfied with her.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.08','deity.egyptian.heqet','NARRATIVE_ACTION','historical.egyptian.ahmose_queen',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Khnum and Heqet leading Queen Ahmose by the hands to the birth chamber.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.09','historical.egyptian.ahmose_queen','NARRATIVE_ACTION','historical.egyptian.hatshepsut',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Queen Ahmose enthroned with the newborn child amid rows of acclaiming gods and spirits, among them Meskhenet, who blesses the child.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.10','deity.egyptian.amun_ra','NARRATIVE_ACTION','historical.egyptian.hatshepsut',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Hathor presenting the newborn to Amun, who greets her as his daughter, beloved Maatkare, the king who takes possession of the Two Lands on the throne of Horus for ever.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.11','deity.egyptian.hathor','NARRATIVE_ACTION','historical.egyptian.hatshepsut',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Hathor and the nurse goddesses suckling Hatshepsut and her ka at Amun''s command, with the child and her ka also drinking from divine cows.','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.hatshepsut_birth.12','deity.egyptian.amun_ra','NARRATIVE_ACTION','historical.egyptian.hatshepsut',NULL,NULL,'The divine birth cycle at Deir el-Bahari shows Thoth presenting Hatshepsut and her ka to Amun (Brunner''s scene 14) and the gods fixing the child''s lifetime (scene 15).','v0360.hatshepsut_birth','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hatshepsut''s birth cycle, Deir el-Bahari',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.01','historical.egyptian.shabaka','NARRATIVE_ACTION','deity.egyptian.ptah',NULL,NULL,'The Shabaka Stone (BM EA 498) opens with King Shabaka''s statement that he found the text as a worm-eaten work of the ancestors in the house of his father Ptah and copied it anew so that his name might endure.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.02','deity.egyptian.ptah','BEARS_TITLE',NULL,'Ta-tenen, South-of-his-Wall, Lord of Eternity, uniter of the land','string','The Shabaka Stone (BM EA 498) calls Ptah the King of Upper and Lower Egypt under the great name Ta-tenen, South-of-his-Wall, Lord of Eternity, the uniter of this land.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.03','deity.egyptian.geb','NARRATIVE_ACTION',NULL,'divides Egypt between Seth in Upper Egypt and Horus in Lower Egypt','string','The Shabaka Stone (BM EA 498) says that Geb gathered the Nine Gods, judged between Horus and Seth, and first made Seth king of Upper Egypt up to Su and Horus king of Lower Egypt up to the place where his father drowned, so that they made peace at Ayan.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.04','deity.egyptian.geb','GAVE_AWAY','deity.egyptian.horus',NULL,NULL,'The Shabaka Stone (BM EA 498) says that it seemed wrong to Geb that Horus''s portion equalled Seth''s, so he gave his whole inheritance to Horus, who as uniter of the land was proclaimed Ta-tenen and wore the two crowns, uniting the Two Lands in the Wall Nome.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.05','deity.egyptian.seth','NARRATIVE_ACTION',NULL,'is reconciled with Horus in the house of Ptah, the Balance of the Two Lands','string','The Shabaka Stone (BM EA 498) says that reed and papyrus were placed on the double door of the house of Ptah, meaning that Horus and Seth were pacified and united in the house of Ptah, the Balance of the Two Lands; a long section after this is worn away.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.06','deity.egyptian.ptah','NARRATIVE_ACTION','deity.egyptian.atum',NULL,NULL,'The Shabaka Stone (BM EA 498) lists the gods who came into being as Ptah, among them Ptah-Nun, the father who made Atum, Ptah-Naunet, the mother who bore Atum, and Ptah the Great, heart and tongue of the Nine Gods.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.07','deity.egyptian.ptah','CREATOR_OF',NULL,'all the gods and their kas, through his heart and his tongue','string','The Shabaka Stone (BM EA 498) says that the form of Atum took shape in Ptah''s heart and on his tongue, that Ptah gave life to all the gods and their kas through his heart and tongue, in which Horus and Thoth took shape as Ptah, and that heart and tongue rule all limbs of every living being.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.08','deity.egyptian.ptah','NARRATIVE_ACTION',NULL,'brings forth Shu and Tefnut by the teeth and lips that name every thing','string','The Shabaka Stone (BM EA 498) contrasts Atum''s Ennead, born of his semen and fingers, with Ptah''s Ennead, the teeth and lips of the mouth that pronounced the name of every thing, from which Shu and Tefnut came forth.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.09','deity.egyptian.ptah','CREATOR_OF',NULL,'gods, kas, justice, life and death and all crafts by the word of heart and tongue','string','The Shabaka Stone (BM EA 498) says that the senses report to the heart, which brings forth understanding, and the tongue announces it, so that all the gods, the kas, food, justice and punishment, life and death, and all labour and crafts came about through what Ptah''s heart devised and his tongue commanded.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.10','deity.egyptian.ptah','NARRATIVE_ACTION',NULL,'rests, satisfied, after making all things and all divine words','string','The Shabaka Stone (BM EA 498) says that Ptah is called he who made all and created the gods, Ta-tenen from whom all good things came forth, the mightiest of the gods, and that Ptah rested (was satisfied) after he had made all things and all divine words.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.11','deity.egyptian.ptah','CREATOR_OF',NULL,'the towns, nomes, shrines and bodies of the gods of wood, stone and clay','string','The Shabaka Stone (BM EA 498) says that Ptah made the towns and nomes, placed the gods in their shrines, settled their offerings and made their bodies of wood, stone and clay, so that the gods entered their bodies and were gathered to him, content.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.memphite.12','deity.egyptian.isis','NARRATIVE_ACTION','deity.egyptian.osiris',NULL,NULL,'The Shabaka Stone (BM EA 498) says that Osiris drowned in his water, that at Horus''s command Isis and Nephthys grasped him and brought him to land, that he entered the earth at the Royal Fortress north of Memphis, and that Horus arose as king in his father''s arms.','v0360.memphite','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Memphite Theology (Shabaka Stone)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.01','deity.ugaritic.baal','NARRATIVE_ACTION',NULL,'feasts with a great cup after his victory over Yamm','string','The Ugaritic Baal Cycle, KTU 1.3 I, describes Baal at a feast, served by Radmanu with a great cup that no woman, not even Athirat, had seen, filled with a thousand jars of wine, while a singer sang of Baal on the heights of Saphon.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.02','deity.ugaritic.anat','NARRATIVE_ACTION',NULL,'fights in the valley and washes her hands in Baal''s dew and rain','string','The Ugaritic Baal Cycle, KTU 1.3 II, describes Anat fighting in the valley, wading in blood with heads and hands bound to her, fighting again in her house with furniture as warriors, and finally washing her hands in the dew of heaven and the rain of the Rider of the Clouds.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.03','deity.ugaritic.baal','NARRATIVE_ACTION','deity.ugaritic.anat',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.3 III, says that Baal sent his messengers Gupn and Ugar to bid Anat remove war from the earth, set love in the land and come to Saphon, where he would reveal to her the word of the tree and the whisper of the stone, the lightning the heavens do not know.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.04','deity.ugaritic.anat','NARRATIVE_ACTION',NULL,'lists the foes she has destroyed for Baal','string','The Ugaritic Baal Cycle, KTU 1.3 III–IV, says that Anat, seeing Baal''s messengers, feared an enemy had risen against Baal and listed the foes she had destroyed — Yamm, River, Tunnan, the seven-headed serpent and others — until the messengers reassured her and she went to Baal on Saphon.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.05','deity.ugaritic.anat','NARRATIVE_ACTION','deity.ugaritic.el',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.3 IV–V, says that Baal lamented to Anat that he had no house like the gods, and that Anat went to El at the source of the rivers, threatened to make his grey hair run with blood and declared that Mightiest Baal was their king, though El''s answer is lost.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.06','deity.ugaritic.kothar_wa_khasis','NARRATIVE_ACTION',NULL,'is summoned from Kaphtor and Hikpat','string','The Ugaritic Baal Cycle, KTU 1.3 VI, says that a messenger was sent across the sea to Kothar-wa-Khasis at Kaphtor, his throne, and Hikpat, his inheritance.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.07','deity.ugaritic.kothar_wa_khasis','CREATOR_OF','deity.ugaritic.asherah',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.4 I, repeats Baal''s lament for a house and describes Kothar-wa-Khasis smelting silver and gold to make a dais, footstool, couch, table and bowls as gifts for Athirat.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.08','deity.ugaritic.asherah','NARRATIVE_ACTION','deity.ugaritic.baal',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.4 II, says that Athirat, spinning by the sea, feared when she saw Baal and Anat coming that they had come to smite her sons, but rejoiced when she saw the silver and gold.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.09','deity.ugaritic.asherah','NARRATIVE_ACTION',NULL,'asks Baal and Anat why they entreat her rather than Bull El','string','The Ugaritic Baal Cycle, KTU 1.4 III, says that after Baal complained of insults in the assembly of the gods, he and Anat brought gifts to Athirat, who asked why they entreated her rather than Bull El, and Anat replied that they would entreat her first and El afterwards.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.10','deity.ugaritic.asherah','NARRATIVE_ACTION','deity.ugaritic.el',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.4 IV, says that Athirat rode a donkey saddled with silver and gold to El at the source of the rivers, and that El smiled, offered her food and wine and asked whether his love had stirred her.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.11','deity.ugaritic.el','NARRATIVE_ACTION','deity.ugaritic.baal',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.4 IV–V, says that when Athirat declared that Mightiest Baal was their king and had no house, El replied that he was no slave to make bricks and granted that a house be built for Baal, and Athirat rejoiced that Baal would now give his rain and thunder in their season.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.12','deity.ugaritic.baal','NARRATIVE_ACTION','deity.ugaritic.kothar_wa_khasis',NULL,NULL,'The Ugaritic Baal Cycle, KTU 1.4 V–VI, says that Anat brought Baal the news of El''s consent, that Baal summoned Kothar-wa-Khasis to build the house, and that when Kothar proposed a window Baal refused, Kothar answering that Baal would return to his word.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.13','deity.ugaritic.baal','NARRATIVE_ACTION',NULL,'rejoices in a house of silver and a palace of gold refined in fire','string','The Ugaritic Baal Cycle, KTU 1.4 VI, says that cedars from Lebanon and Sirion were cut, that fire burned in the house for six days and on the seventh the silver had turned into plates and the gold into bricks, and that Baal held a feast for the seventy sons of Athirat.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.baal_palace.14','deity.ugaritic.baal','NARRATIVE_ACTION',NULL,'thunders from his palace window and sends messengers to Mot','string','The Ugaritic Baal Cycle, KTU 1.4 VII–VIII, says that Baal seized sixty-six cities and seventy-seven towns, then had Kothar open the window, gave forth his holy voice through a rift in the clouds so that the earth quaked and his enemies fled, and sent Gupn and Ugar to Mot.','v0360.baal_palace','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Baal Cycle, KTU 1.3–1.4',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.01','text.sumerian.inana_ebih','DESCRIBED_AS',NULL,'opens with a hymn to Inana, goddess of the fearsome divine powers','string','The Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2) opens by praising Inana as goddess of the fearsome divine powers, clad in terror, drenched in blood, rushing through great battles and destroying mighty lands with arrow and strength.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.02','text.sumerian.inana_ebih','DESCRIBED_AS',NULL,'praises Inana roaring like a lion so that the Anuna gods flee','string','The Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2) praises Inana as roaring like a lion and rushing like a wild bull in heaven and on earth, so that the Anuna gods flee before her like birds and bats.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.03','place.sumerian.ebih','NARRATIVE_ACTION',NULL,'does not bow to Inana, nor put its nose to the ground for her','string','In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana says that when she walked through heaven and earth and approached the mountain range Ebiḫ, it showed her no respect, did not put its nose to the ground nor rub its lips in the dust for her.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.04','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'vows to fill Ebiḫ with terror like a city cursed by An','string','In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana vows to fill the mountain range with terror, to bring battering rams, axes and arrows against it, to burn its forests, and to make it like a city cursed by An that is never restored.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.05','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'puts on the garments of queenship and grasps the seven-headed mace','string','In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana, daughter of Suen, puts on the garments of queenship, terror and radiance and carnelian rosettes, grasps the seven-headed mace and sets out at dawn.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.06','deity.sumerian.inanna','NARRATIVE_ACTION','deity.sumerian.an',NULL,NULL,'In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana prostrates herself before An, greets him as her father, recalls that he made her terrifying in heaven and on earth, and asks leave to bring Ebiḫ low for showing her no respect.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.07','deity.sumerian.an','NARRATIVE_ACTION','deity.sumerian.inanna',NULL,NULL,'In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), An answers Inana by asking what his little one is taking on in demanding the mountain''s destruction, warning that Ebiḫ has spread terror over the dwellings of the gods and is rich in fruit, lions and wild bulls, so that she cannot go against it.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.08','deity.sumerian.inanna','NARRATIVE_ACTION','place.sumerian.ebih',NULL,NULL,'In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana, in rage after An''s answer, opens the gate of the house of battle and the lapis lazuli door and brings out battle, flood and an evil storm against Ebiḫ.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.09','place.sumerian.ebih','NARRATIVE_ACTION',NULL,'is seized by the neck by Inana and laid waste with drought and fire','string','In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana seizes Ebiḫ by the neck, presses her dagger into it, roars like thunder, makes its stones clatter down, kills its oaks with drought and pours fire on its slopes.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.inana_ebih.10','deity.sumerian.inanna','NARRATIVE_ACTION','place.sumerian.ebih',NULL,NULL,'In the Sumerian composition Inana and Ebiḫ (ETCSL 1.3.2), Inana declares that she has killed the mountain range because of its height and beauty and because it did not bow to her, builds a temple there, and the poem closes in praise of Inana for destroying Ebiḫ.','v0360.inana_ebih','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana and Ebiḫ (ETCSL 1.3.2)',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.01','deity.chinese.leigong','DESCRIBED_AS',NULL,'thunder as Heaven taking dragons and punishing hidden faults in common belief','string','Wang Chong, Lunheng, ''Lei Xu'', records the common belief that summer thunder that splits trees and wrecks houses is Heaven taking a dragon, and that thunder which kills a man is Heaven''s anger punishing a hidden fault, such as feeding people unclean food, the rumbling being Heaven''s angry voice.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.02','deity.chinese.leigong','DESCRIBED_AS',NULL,'the rumbling held to be Heaven''s angry voice, which Wang Chong disputes','string','Wang Chong, Lunheng, ''Lei Xu'', argues that since the same thunder at the same moment both splits trees and kills people, it cannot be both Heaven auspiciously taking a dragon and Heaven angrily punishing a fault, and asks what fault a dragon has that Heaven should be angry.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.03','deity.chinese.leigong','DESCRIBED_AS',NULL,'strikes by chance those who happen to be under trees or in houses, according to Wang Chong','string','Wang Chong, Lunheng, ''Lei Xu'', concludes that a man under a tree or in a house who is struck by thunder has merely been hit by chance, and so denies that thunder singles people out for their faults.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.04','deity.chinese.leigong','DEPICTS',NULL,'a strongman pulling linked drums with his left hand and raising a mallet with his right','string','Wang Chong, Lunheng, ''Lei Xu'', says that painters depicted thunder as linked drums and a strongman called Leigong pulling the drums with his left hand and raising a mallet with his right, the rumbling being the drums and the crack the mallet, and calls the image false.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.05','deity.chinese.leigong','DESCRIBED_AS',NULL,'drawn without wings, which Wang Chong argues contradicts his flying in the sky','string','Wang Chong, Lunheng, ''Lei Xu'', objects that thunder is a sound or breath that cannot be made into drums, asks where Leigong''s drums hang and where he stands, and argues that since painters give flying immortals wings, a flying Leigong drawn without wings is a contradiction.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.06','deity.chinese.leigong','DESCRIBED_AS',NULL,'thunder explained as fire by five proofs rather than as Leigong''s drums','string','Wang Chong, Lunheng, ''Lei Xu'', gives five proofs that thunder is fire: the singed hair, burned skin and smell of fire on those it kills; red-hot stones thrown into wells; the rumbling of a chilled belly; the fire-like flash of lightning; and the burning of houses and plants.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.07','deity.chinese.leigong','DESCRIBED_AS',NULL,'explained as fire meeting water in the furnace of heaven and earth','string','Wang Chong, Lunheng, ''Lei Xu'', compares thunder to a peck of water poured on a smelting furnace, which bursts with a thunderous crack, calling heaven and earth a great furnace, yang energy its fire and clouds and rain its water.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z'),
('claim.v0360.leigong_leixu.08','deity.chinese.leigong','DESCRIBED_AS',NULL,'reduced by Wang Chong to the surging energy of great yang','string','Wang Chong, Lunheng, ''Lei Xu'', concludes that thunder is the surging energy of great yang, beginning in the first month, fiercest in the fifth and hidden in autumn and winter, produced when yin and yang contend in summer, so that it kills, breaks or wrecks whatever it happens to strike.','v0360.leigong_leixu','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Wang Chong, Lunheng, "Lei Xu"',NULL,NULL,'2026-10-24T22:00:00Z');

