INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.1','storyver.greek.hymn3_apollo_evelyn_white',1,'众神起身','The gods rise','诗人一开头就说，他要歌颂远射之神阿波罗，因为当阿波罗走进宙斯的宫殿时，众神都在他面前发抖，纷纷从座位上站起来，只有母亲勒托还安坐在宙斯身边。','The poet begins by saying he will sing of Apollo who shoots from afar, before whom the gods tremble when he enters the house of Zeus: they all rise from their seats, and only Leto his mother stays seated beside Zeus.','claim.v0360.hym_apollo.01',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.2','storyver.greek.hymn3_apollo_evelyn_white',2,'无处安身','No place to rest','勒托怀着远射之神，走遍了希腊的土地和岛屿，想找一个肯让她生产的地方。','Carrying the far-shooting god, Leto went through the lands and islands of Greece looking for a place that would let her give birth.','claim.v0360.hym_apollo.02',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.3','storyver.greek.hymn3_apollo_evelyn_white',3,'得洛斯的誓言','The oath on Delos','勒托来到得洛斯，对这座小岛说：得洛斯啊，你愿意做我儿子福玻斯·阿波罗的家，在你这里为他建一座丰盛的神庙吗？','Leto came to Delos and said to the island: ''Delos, would you be the home of my son Phoebus Apollo and let him build a rich temple on you?','claim.v0360.hym_apollo.03',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.4','storyver.greek.hymn3_apollo_evelyn_white',4,'被拦住的生育女神','The birth goddess kept away','勒托在得洛斯开始了阵痛，一连九天九夜，痛苦难当。','On Delos Leto was racked with labour for nine days and nine nights.','claim.v0360.hym_apollo.04',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.5','storyver.greek.hymn3_apollo_evelyn_white',5,'棕榈树下','Under the palm tree','厄勒梯亚一踏上得洛斯，阵痛就攫住了勒托，她就要生了。','As soon as Eileithyia set foot on Delos, the pains took hold of Leto and she was ready to give birth.','claim.v0360.hym_apollo.05',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.6','storyver.greek.hymn3_apollo_evelyn_white',6,'弓与竖琴','The bow and the lyre','福玻斯一尝到神食，金色的襁褓就再也包不住他了，身上的带子也束不住他，所有的布条都松开了。','As soon as Phoebus had tasted ambrosia, the golden swaddling bands could no longer hold him, nor could the cords restrain him; all the bands fell loose.','claim.v0360.hym_apollo.06',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.7','storyver.greek.hymn3_apollo_evelyn_white',7,'得洛斯的节日','The festival on Delos','诗人描写了得洛斯的盛会：穿着长袍的伊奥尼亚人带着妻儿聚集到岛上来纪念阿波罗，用拳击、舞蹈和歌唱来取悦他。','The poet describes the gathering on Delos: the long-robed Ionians come together with their children and wives to honour Apollo, delighting him with boxing, dancing and song.','claim.v0360.hym_apollo.07',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.8','storyver.greek.hymn3_apollo_evelyn_white',8,'奥林波斯的舞蹈','The dance on Olympus','颂歌的第二部分换了一个场景。','The second part of the hymn changes scene.','claim.v0360.hym_apollo.08',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.9','storyver.greek.hymn3_apollo_evelyn_white',9,'泰尔福萨的诡计','Telphusa''s trick','诗人又问：我该怎样歌颂你呢？','Again the poet asks how he should sing of the god, and chooses to tell how Apollo sought a place to found an oracle for men.','claim.v0360.hym_apollo.09',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.10','storyver.greek.hymn3_apollo_evelyn_white',10,'神庙的地基与泉边的母龙','The foundations and the dragon at the spring','阿波罗来到佛勒古埃斯人的城市，又走上帕尔纳索斯山下积雪的山坡，来到克里萨。','Apollo came to the city of the Phlegyae and up the snowy slopes below Parnassus to Crisa, a shoulder of the hill turned westward, with a great cliff hanging over it and a hollow, rugged glen below.','claim.v0360.hym_apollo.10',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.11','storyver.greek.hymn3_apollo_evelyn_white',11,'赫拉独自生下的孩子','The child Hera bore alone','诗人在这里插进了一段旧事。','Here the poet tells an older story.','claim.v0360.hym_apollo.11',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.12','storyver.greek.hymn3_apollo_evelyn_white',12,'皮托这个名字','How Pytho got its name','凡是遇上这条母龙的人，末日都会到来，直到远射之神阿波罗向她射出一支强劲的箭。','Whoever met the she-dragon, the day of doom swept him away, until far-shooting Apollo let fly a strong arrow at her.','claim.v0360.hym_apollo.12',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.13','storyver.greek.hymn3_apollo_evelyn_white',13,'海豚','The dolphin','神庙建好了，福玻斯·阿波罗开始考虑，该找什么样的人来在多岩的皮托做他的祭司，为他主持祭祀。','When the temple was built, Phoebus Apollo pondered what men he should bring to be his ministers in rocky Pytho.','claim.v0360.hym_apollo.13',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn3_apollo_evelyn_white.14','storyver.greek.hymn3_apollo_evelyn_white',14,'德尔斐的祭司','The priests of Delphi','船靠了岸，远射之神阿波罗像一颗正午的星星一样从船上跃出，火花四溅，光芒直冲天际。','When the ship came to shore, far-shooting Apollo leapt from it like a star at midday, sparks flying from him and the brightness reaching to heaven.','claim.v0360.hym_apollo.14',NULL,'site.greece.delos','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.1','storyver.greek.hymn4_hermes_evelyn_white',1,'洞中的仙女','The nymph in the cave','诗人请缪斯歌唱赫尔墨斯，宙斯和迈亚的儿子，库勒涅山和牛羊成群的阿卡狄亚的主人，众神迅捷的使者。','The poet asks the Muse to sing of Hermes, son of Zeus and Maia, lord of Cyllene and of Arcadia rich in flocks, swift messenger of the gods.','claim.v0360.hym_hermes.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.2','storyver.greek.hymn4_hermes_evelyn_white',2,'乌龟变成竖琴','The tortoise becomes a lyre','赫尔墨斯从母亲不朽的怀里一跳下来，就不肯安安静静地躺在神圣的摇篮里，跨过高高的门槛，去找阿波罗的牛群。','As soon as Hermes leapt from his mother''s immortal womb he would not lie still in his holy cradle, but sprang over the threshold of the high-roofed cave to look for Apollo''s cattle.','claim.v0360.hym_hermes.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.3','storyver.greek.hymn4_hermes_evelyn_white',3,'五十头牛','Fifty cattle','可是赫尔墨斯心里想的是别的事。','But Hermes had other things in mind.','claim.v0360.hym_hermes.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.4','storyver.greek.hymn4_hermes_evelyn_white',4,'昂刻斯托斯的老人','The old man at Onchestus','赫尔墨斯赶着牛穿过平原，经过鲜花盛开的昂刻斯托斯时，一个老人正在葡萄园里劳作，看见了这个赶牛的孩子。','As Hermes drove the cattle across the plain past flowery Onchestus, an old man tending his vineyard saw the child driving them.','claim.v0360.hym_hermes.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.5','storyver.greek.hymn4_hermes_evelyn_white',5,'阿尔甫斯河边的火','Fire by the Alpheus','到了阿尔甫斯河边，赫尔墨斯捡来许多木柴，开始想办法生火。','At the Alpheus Hermes gathered a pile of wood and began to seek the art of fire.','claim.v0360.hym_hermes.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.6','storyver.greek.hymn4_hermes_evelyn_white',6,'母亲的责备','His mother''s rebuke','天亮以前，赫尔墨斯回到了库勒涅山的高峰。','Before dawn Hermes came back to the bright peaks of Cyllene.','claim.v0360.hym_hermes.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.7','storyver.greek.hymn4_hermes_evelyn_white',7,'阿波罗寻牛','Apollo seeks his cattle','黎明从大洋深处升起，给人们带来光明。','Dawn rose from deep-flowing Ocean bringing light to men, and Apollo came to holy Onchestus, where he found the old man tending the hedge of his vineyard by the road.','claim.v0360.hym_hermes.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.8','storyver.greek.hymn4_hermes_evelyn_white',8,'库勒涅的山洞','The cave on Cyllene','阿波罗来到库勒涅山林木茂盛的山上，来到岩石中幽深的山洞，那是不死的仙女迈亚生下宙斯之子的地方。','Apollo came to the wooded mountain of Cyllene, to the deep cave in the rock where the deathless nymph Maia had borne the child of Zeus.','claim.v0360.hym_hermes.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.9','storyver.greek.hymn4_hermes_evelyn_white',9,'去见宙斯','To Zeus','赫尔墨斯一边说，一边眼睛不停地眨着，眉毛扬来扬去，四处张望，吹着长长的口哨，像在听一个无聊的故事。','As he spoke, Hermes kept glancing about with twinkling eyes, his brows going up and down, and gave a long whistle, as if listening to an idle tale.','claim.v0360.hym_hermes.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.10','storyver.greek.hymn4_hermes_evelyn_white',10,'宙斯的判断','The judgement of Zeus','两位神来到芬芳的奥林波斯山顶，来到父亲宙斯面前，正义的天平就摆在那里。','The two came to the summit of fragrant Olympus, to their father Zeus, where the scales of judgement were set.','claim.v0360.hym_hermes.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.11','storyver.greek.hymn4_hermes_evelyn_white',11,'竖琴换牛群','The lyre for the cattle','两兄弟来到阿尔甫斯河边的牛棚，赫尔墨斯把牛从石洞里赶了出来。','The brothers came to the byre by the Alpheus, and Hermes drove the cattle out of the rocky cave.','claim.v0360.hym_hermes.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn4_hermes_evelyn_white.12','storyver.greek.hymn4_hermes_evelyn_white',12,'兄弟的盟约','The brothers'' pact','两兄弟赶着牛群回到神圣的草地，然后回到积雪的奥林波斯山，宙斯看见他们和好，心里很高兴。','The brothers drove the cattle back to the holy meadow and returned to snowy Olympus, and Zeus was glad to see them reconciled.','claim.v0360.hym_hermes.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.1','storyver.greek.hymn5_aphrodite_evelyn_white',1,'阿佛洛狄忒的力量与雅典娜','Aphrodite''s power, and Athena','诗人请缪斯歌唱金色的阿佛洛狄忒，塞浦路斯的女神。','The poet asks the Muse to tell of golden Aphrodite, the Cyprian, who stirs sweet desire in the gods and subdues the tribes of mortal men, the birds that fly in the air and all the creatures of dry land and sea: all of them care for her works.','claim.v0360.hym_aphrodite.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.2','storyver.greek.hymn5_aphrodite_evelyn_white',2,'阿耳忒弥斯','Artemis','第二位是戴着金冠、喜爱喧闹的狩猎女神阿耳忒弥斯，爱笑的阿佛洛狄忒从来不能用爱情制服她。','The second is Artemis of the golden arrows and the loud hunting cry, whom laughter-loving Aphrodite never tames in love.','claim.v0360.hym_aphrodite.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.3','storyver.greek.hymn5_aphrodite_evelyn_white',3,'赫斯提亚的誓言','Hestia''s vow','第三位是可敬的处女赫斯提亚，阿佛洛狄忒的事业同样不能让她高兴。','The third is the revered maiden Hestia, whom Aphrodite''s works do not please either.','claim.v0360.hym_aphrodite.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.4','storyver.greek.hymn5_aphrodite_evelyn_white',4,'宙斯的回敬','Zeus''s answer','除了这三位，无论是有福的神还是会死的人，没有谁能躲开阿佛洛狄忒。','Apart from these three, there is nothing among the blessed gods or mortal men that has escaped Aphrodite.','claim.v0360.hym_aphrodite.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.5','storyver.greek.hymn5_aphrodite_evelyn_white',5,'帕福斯与伊达山','Paphos and Ida','爱笑的阿佛洛狄忒一看见安喀塞斯，就爱上了他，强烈的渴望攫住了她的心。','When laughter-loving Aphrodite saw Anchises she loved him, and desire seized her heart.','claim.v0360.hym_aphrodite.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.6','storyver.greek.hymn5_aphrodite_evelyn_white',6,'牧人小屋','At the herdsman''s hut','她发现安喀塞斯独自一人留在小屋里，他有着众神赐予的美貌。','She found Anchises left alone at the huts, with beauty given by the gods.','claim.v0360.hym_aphrodite.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.7','storyver.greek.hymn5_aphrodite_evelyn_white',7,'弗里吉亚的公主','The Phrygian princess','宙斯的女儿阿佛洛狄忒回答说：安喀塞斯，你是地上的人中最光荣的，我不是女神，你为什么把我比作不死的神？','Aphrodite, daughter of Zeus, answered: ''Anchises, most glorious of earth-born men, I am no goddess; why do you liken me to the deathless ones?','claim.v0360.hym_aphrodite.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.8','storyver.greek.hymn5_aphrodite_evelyn_white',8,'婚床','The marriage bed','女神说着，把甜蜜的渴望放进了安喀塞斯的心里。','So speaking, the goddess put sweet desire in Anchises'' heart.','claim.v0360.hym_aphrodite.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.9','storyver.greek.hymn5_aphrodite_evelyn_white',9,'醒来的恐惧','The fear on waking','女神穿好衣服，站在小屋里，头几乎碰到精工建造的屋顶，脸颊上闪耀着不朽的美，那是戴着美丽花冠的库忒瑞亚才有的美。','Clothed again, the goddess stood in the hut, her head reaching to the well-hewn roof-beam, and from her cheeks shone unearthly beauty such as belongs to rich-crowned Cytherea.','claim.v0360.hym_aphrodite.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.10','storyver.greek.hymn5_aphrodite_evelyn_white',10,'埃涅阿斯与伽倪墨得斯','Aeneas and Ganymede','宙斯的女儿阿佛洛狄忒回答说：安喀塞斯，凡人中最光荣的人，鼓起勇气，不要太害怕。','Aphrodite, daughter of Zeus, answered: ''Anchises, most glorious of mortal men, take courage and do not fear too much.','claim.v0360.hym_aphrodite.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.11','storyver.greek.hymn5_aphrodite_evelyn_white',11,'厄俄斯与提托诺斯','Eos and Tithonus','阿佛洛狄忒又讲了另一个特洛伊人的故事。','Aphrodite told of another Trojan.','claim.v0360.hym_aphrodite.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_hymn5_aphrodite_evelyn_white.12','storyver.greek.hymn5_aphrodite_evelyn_white',12,'山中的仙女','The nymphs of the mountain','阿佛洛狄忒说：如果你能保持现在的容貌和身材活下去，被称为我的丈夫，悲伤就不会笼罩我的心。','Aphrodite said: ''If you could live on as you are now in looks and form, and be called my husband, sorrow would not enfold my heart.','claim.v0360.hym_aphrodite.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.1','storyver.greek.theogony_titans_children',1,'混沌之子','The children of Chaos','赫西俄德说，最先出现的是混沌卡俄斯，接着是宽胸的大地盖亚，她是住在积雪的奥林波斯山顶上的众神永远稳固的根基；然后是道路宽阔的大地深处幽暗的塔耳塔罗斯；还有爱神厄洛斯，不死的神中最美的一位，他能松弛四肢，征服所有神和人的心智与谋划。','Hesiod says that first of all Chaos came to be, and next wide-bosomed Earth, the ever-sure foundation of all the deathless ones who hold the peaks of snowy Olympus; and dim Tartarus in the depth of the wide-pathed Earth; and Eros, fairest among the deathless gods, who unnerves the limbs and overcomes the mind and wise counsels of all gods and men.','claim.v0360.theog_titans.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.2','storyver.greek.theogony_titans_children',2,'埃忒耳与赫墨拉','Aether and Hemera','接下来，《神谱》说，黑夜和厄瑞玻斯相爱结合，黑夜怀孕，生下了埃忒耳和赫墨拉。','Next, the Theogony says, Night conceived in love with Erebus and bore Aether and Hemera.','claim.v0360.theog_titans.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.3','storyver.greek.theogony_titans_children',3,'十二位提坦','The twelve Titans','大地首先生下了和她一样大的繁星点点的天空乌拉诺斯，让他把自己完全覆盖，作为众神永远稳固的居所；她又生下了高高的群山，那是住在山谷里的仙女们喜爱的地方；她还不经过爱情，生下了波涛汹涌的荒凉大海蓬托斯。','Earth first bore starry Heaven, equal to herself, to cover her on every side and be an ever-sure abiding place for the blessed gods; she brought forth the long hills, graceful haunts of the nymphs who dwell in the glens; and she bore also the fruitless deep with its raging swell, Pontus, without sweet union of love.','claim.v0360.theog_titans.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.4','storyver.greek.theogony_titans_children',4,'夜的子女','The children of Night','在讲完克洛诺斯怎样阉割天空、阿佛洛狄忒怎样从海沫中诞生之后，《神谱》回到了黑夜身上。','After telling how Cronos maimed Heaven and how Aphrodite was born of the sea-foam, the Theogony turns back to Night.','claim.v0360.theog_titans.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.5','storyver.greek.theogony_titans_children',5,'海的女儿','The daughter of the Sea','接下来，赫西俄德讲大海蓬托斯的家族。','Next Hesiod tells of the family of Pontus, the Sea.','claim.v0360.theog_titans.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.6','storyver.greek.theogony_titans_children',6,'太阳、月亮与黎明','Sun, Moon and Dawn','在讲完大洋的女儿们和河流之后，《神谱》说：忒亚和许珀里翁相爱结合，生下了伟大的太阳赫利俄斯、明亮的月亮塞勒涅和黎明厄俄斯——厄俄斯为大地上的一切生灵、也为住在宽阔天空中的不死的神照亮道路。','After the daughters of Ocean and the rivers, the Theogony says: Theia, subject in love to Hyperion, bore great Helios and clear Selene and Eos, who shines upon all that are on earth and upon the deathless gods who live in wide heaven.','claim.v0360.theog_titans.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.7','storyver.greek.theogony_titans_children',7,'克利俄斯的儿子们','The sons of Crius','紧接着，《神谱》说：欧律比亚，女神中光彩照人的一位，与克利俄斯相爱结合，生下了伟大的阿斯特赖俄斯、帕拉斯，还有在所有人中以智慧出众的珀耳塞斯。','Next the Theogony says: Eurybia, bright among goddesses, was joined in love with Crius and bore great Astraeus, and Pallas, and Perses, who was eminent among all men in wisdom.','claim.v0360.theog_titans.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.8','storyver.greek.theogony_titans_children',8,'风与星辰','Winds and stars','接着，诗人说：黎明女神厄俄斯和阿斯特赖俄斯——一位女神和一位神——在爱中结合，生下了心意强壮的风：吹得天空晴朗的西风仄费洛斯、迅猛的北风玻瑞阿斯和南风诺托斯。','Then the poet says: Eos, a goddess, bore to Astraeus, a god, the strong-hearted winds — brightening Zephyrus, swift Boreas and Notus — in union of love.','claim.v0360.theog_titans.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.9','storyver.greek.theogony_titans_children',9,'斯梯克斯的孩子','The children of Styx','大洋的女儿斯梯克斯与帕拉斯结合，在自己的宫殿里生下了泽洛斯和脚踝美丽的尼刻——竞争与胜利，又生下了克拉托斯和比亚——力量与暴力，这两个孩子都非常出色。','Styx, daughter of Ocean, was joined with Pallas and bore Zelos and trim-ankled Nike — Rivalry and Victory — in the house, and also Kratos and Bia — Strength and Force — wonderful children.','claim.v0360.theog_titans.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.10','storyver.greek.theogony_titans_children',10,'众神的誓言','The oath of the gods','诗人接着讲斯梯克斯为什么享有这样的荣誉。','The poet then tells why Styx has such honour.','claim.v0360.theog_titans.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.11','storyver.greek.theogony_titans_children',11,'福柏的女儿们','The daughters of Phoebe','提坦福柏来到科俄斯的爱床，女神在男神的爱中怀孕，生下了穿着深色长袍的勒托。','Phoebe came to the desired bed of Coeus, and the goddess, conceiving in the love of the god, bore dark-gowned Leto.','claim.v0360.theog_titans.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.12','storyver.greek.theogony_titans_children',12,'赫卡忒的荣耀','The honour of Hecate','阿斯忒里亚怀了孕，生下了赫卡忒。','Asteria conceived and bore Hecate, and the poet praises her at length: Zeus the son of Cronos honoured her above all and gave her splendid gifts, a share of the earth and the unfruitful sea, and honour in starry heaven, and she is honoured most of all by the deathless gods.','claim.v0360.theog_titans.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.13','storyver.greek.theogony_titans_children',13,'夜与昼的门槛','The threshold of Night and Day','在描写宙斯战胜提坦、把他们关进塔耳塔罗斯之后，诗人带领听众来到世界的边缘。','After describing how Zeus overcame the Titans and shut them in Tartarus, the poet leads his hearers to the edge of the world.','claim.v0360.theog_titans.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.14','storyver.greek.theogony_titans_children',14,'睡与死的住所','The house of Sleep and Death','就在那里，幽暗黑夜的孩子们也有自己的住所：睡眠和死亡，两位可怕的神。','There too the children of dark Night have their dwellings, Sleep and Death, awful gods.','claim.v0360.theog_titans.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_theogony_titans_children.15','storyver.greek.theogony_titans_children',15,'厄俄斯的儿子们','The sons of Eos','《神谱》快结束时，诗人列出了女神与凡间男子所生的孩子。','Near the end of the Theogony the poet lists the children goddesses bore to mortal men.','claim.v0360.theog_titans.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.1','storyver.greek.library_artemis',1,'勒托的孪生子女','Leto''s twins','《书库》在讲提坦的子女时说，科俄斯的女儿阿斯忒里亚为了躲避宙斯，化作一只鹌鹑跳进大海，那座城市先是叫阿斯忒里亚，后来叫得洛斯。','Telling of the Titans'' children, the Library says that Asteria, daughter of Coeus, fled Zeus in the likeness of a quail and flung herself into the sea, and a city was called Asteria after her and later Delos.','claim.v0360.lib_artemis.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.2','storyver.greek.library_artemis',2,'提堤俄斯','Tityus','同一节里，《书库》讲了一件姐弟俩为母亲报仇的事。','In the same section the Library tells how the twins avenged their mother.','claim.v0360.lib_artemis.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.3','storyver.greek.library_artemis',3,'俄里翁','Orion','《书库》说：阿耳忒弥斯在得洛斯杀死了俄里翁。','The Library says: Artemis slew Orion in Delos.','claim.v0360.lib_artemis.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.4','storyver.greek.library_artemis',4,'阿洛伊代兄弟','The Aloadae','《书库》第一卷还讲了一对巨人兄弟，俄托斯和厄菲阿尔忒斯，人称阿洛伊代兄弟。','In its first book the Library also tells of two giant brothers, Otus and Ephialtes, called the Aloadae — nominally sons of Aloeus, but in truth sons of Poseidon.','claim.v0360.lib_artemis.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.5','storyver.greek.library_artemis',5,'卡吕冬的野猪','The Calydonian boar','埃托利亚的卡吕冬国王俄纽斯在一年的收成之后，把最早的果实献给所有的神，唯独忘了阿耳忒弥斯。','Oeneus, king of Calydon in Aetolia, offering the first-fruits of the year''s crops to all the gods, forgot Artemis alone.','claim.v0360.lib_artemis.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.6','storyver.greek.library_artemis',6,'阿德墨托斯的婚房','Admetus''s bridal chamber','斐赖国王阿德墨托斯向珀利阿斯的女儿阿尔刻提斯求婚。','Admetus, king of Pherae, wooed Alcestis, daughter of Pelias.','claim.v0360.lib_artemis.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.7','storyver.greek.library_artemis',7,'刻律涅亚的牝鹿','The Ceryneian hind','《书库》第二卷讲赫拉克勒斯的十二项任务。','The Library''s second book tells the labours of Heracles.','claim.v0360.lib_artemis.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.8','storyver.greek.library_artemis',8,'阿克泰翁','Actaeon','《书库》第三卷讲忒拜的故事。','The Library''s third book tells the stories of Thebes.','claim.v0360.lib_artemis.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.9','storyver.greek.library_artemis',9,'尼俄柏','Niobe','忒拜王安菲翁娶了坦塔罗斯的女儿尼俄柏，生了七个儿子和七个女儿——《书库》还注明，赫西俄德说他们有十个儿子十个女儿，荷马说有六个儿子六个女儿。','Amphion, king of Thebes, married Niobe, daughter of Tantalus, who bore seven sons and seven daughters — the Library notes that Hesiod gives ten of each and Homer six of each.','claim.v0360.lib_artemis.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.10','storyver.greek.library_artemis',10,'卡利斯托','Callisto','《书库》讲阿卡狄亚的谱系时，提到了卡利斯托。','Recounting the Arcadian line, the Library tells of Callisto.','claim.v0360.lib_artemis.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.11','storyver.greek.library_artemis',11,'奥里斯的风','The winds at Aulis','《书库》的《摘要》部分讲特洛伊战争。','The Epitome of the Library tells of the Trojan War.','claim.v0360.lib_artemis.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_artemis.12','storyver.greek.library_artemis',12,'伊菲革涅亚','Iphigenia','阿伽门农接到神谕后，派奥德修斯和传令官塔尔堤比俄斯去见妻子克吕泰涅斯特拉，向她要伊菲革涅亚，假说他答应把女儿嫁给阿喀琉斯，作为对阿喀琉斯参战的酬谢。','On receiving the oracle Agamemnon sent Odysseus and the herald Talthybius to Clytemnestra to ask for Iphigenia, pretending he had promised to give her to Achilles to wife as a reward for his service.','claim.v0360.lib_artemis.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.1','storyver.greek.library_3_4_3_5_dionysus',1,'塞墨勒的请求','Semele''s request','腓尼基人卡德摩斯建立了忒拜，娶了阿瑞斯和阿佛洛狄忒的女儿哈耳摩尼亚，生下了女儿奥托诺厄、伊诺、塞墨勒和阿高厄，还有儿子波吕多罗斯。','Cadmus the Phoenician founded Thebes and married Harmonia, daughter of Ares and Aphrodite, who bore him daughters, Autonoe, Ino, Semele and Agave, and a son, Polydorus.','claim.v0360.lib_dionysus.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.2','storyver.greek.library_3_4_3_5_dionysus',2,'雷火','Thunder and fire','宙斯无法拒绝，只好驾着战车，带着闪电和雷鸣来到塞墨勒的屋子，掷出了一道雷电。','Unable to refuse, Zeus came to her bridal chamber in a chariot with lightnings and thunderings and launched a thunderbolt.','claim.v0360.lib_dionysus.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.3','storyver.greek.library_3_4_3_5_dionysus',3,'第二次出生','The second birth','塞墨勒死后，卡德摩斯的其他女儿们四处散布流言，说塞墨勒是和一个凡人同床，却谎称是宙斯，所以才被雷电击死。','After Semele''s death the other daughters of Cadmus spread the report that she had lain with a mortal man and falsely accused Zeus, and that she was blasted by the thunderbolt for it.','claim.v0360.lib_dionysus.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.4','storyver.greek.library_3_4_3_5_dionysus',4,'伊诺与阿塔玛斯的疯狂','The madness of Ino and Athamas','可是赫拉还是知道了。','But Hera found out, and in her anger drove Ino and Athamas mad.','claim.v0360.lib_dionysus.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.5','storyver.greek.library_3_4_3_5_dionysus',5,'倪萨的仙女','The nymphs of Nysa','为了不让赫拉再找到他，宙斯把狄俄倪索斯变成了一只小山羊。','To keep him from Hera, Zeus turned Dionysus into a kid, and Hermes took him to the nymphs who dwelt at Nysa in Asia.','claim.v0360.lib_dionysus.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.6','storyver.greek.library_3_4_3_5_dionysus',6,'葡萄与疯狂','The vine and the madness','《书库》第三卷接着说：狄俄倪索斯是葡萄的发现者。','The third book goes on: Dionysus discovered the vine.','claim.v0360.lib_dionysus.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.7','storyver.greek.library_3_4_3_5_dionysus',7,'吕枯耳戈斯','Lycurgus','在色雷斯，斯特律蒙河边的厄多涅斯人的国王、德律阿斯的儿子吕枯耳戈斯第一个侮辱了狄俄倪索斯，把他赶了出去。','In Thrace, Lycurgus son of Dryas, king of the Edonians who dwell beside the river Strymon, was the first to insult and expel Dionysus.','claim.v0360.lib_dionysus.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.8','storyver.greek.library_3_4_3_5_dionysus',8,'回到忒拜','Back to Thebes','狄俄倪索斯穿过色雷斯和整个印度，在那里竖起了石柱，然后来到了忒拜。','Having traversed Thrace and the whole of India and set up pillars there, Dionysus came to Thebes.','claim.v0360.lib_dionysus.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.9','storyver.greek.library_3_4_3_5_dionysus',9,'彭透斯','Pentheus','彭透斯想阻止酒神的仪式，就来到喀泰戎山上，暗中窥探那些狂欢的女人。','To stop the rites Pentheus went to Cithaeron to spy on the raving women.','claim.v0360.lib_dionysus.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.10','storyver.greek.library_3_4_3_5_dionysus',10,'第勒尼安海盗','The Tyrrhenian pirates','狄俄倪索斯想从伊卡里亚岛渡海到纳克索斯岛，就雇了一条第勒尼安海盗的船。','Wishing to be ferried from Icaria to Naxos, Dionysus hired a pirate ship of Tyrrhenians.','claim.v0360.lib_dionysus.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.11','storyver.greek.library_3_4_3_5_dionysus',11,'从冥府带回母亲','Bringing his mother up from Hades','《书库》用一句话为狄俄倪索斯在大地上的游历作了结尾：人们知道了他是神，开始崇拜他；他从冥府带回了自己的母亲，给她取名堤俄涅，和她一起升上了天空。','The Library closes Dionysus''s wanderings on earth in one sentence: men learned that he was a god and honoured him; and having brought up his mother from Hades and named her Thyone, he ascended with her to heaven.','claim.v0360.lib_dionysus.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_library_3_4_3_5_dionysus.12','storyver.greek.library_3_4_3_5_dionysus',12,'伊卡里俄斯','Icarius','《书库》在讲雅典诸王的时候，又提到了狄俄倪索斯。','Telling of the kings of Athens, the Library mentions Dionysus again.','claim.v0360.lib_dionysus.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.1','storyver.greek.iliad_butler_ares',1,'被领出战场','Led from the battle','《伊利亚特》第五卷是狄俄墨得斯大显身手的一卷，也是阿瑞斯在全诗中出场最多的一卷。','Book Five of the Iliad is Diomedes'' great day, and the book in which Ares appears most.','claim.v0360.iliad_ares.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.2','storyver.greek.iliad_butler_ares',2,'借车','The borrowed chariot','战场上，狄俄墨得斯在雅典娜的鼓舞下所向无敌，连阿佛洛狄忒也被他刺伤了手腕——她是来救自己受伤的儿子埃涅阿斯的。','On the field Diomedes, fired by Athena, carries all before him, and he even wounds Aphrodite in the wrist when she comes to rescue her wounded son Aeneas.','claim.v0360.iliad_ares.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.3','storyver.greek.iliad_butler_ares',3,'铜罐里的十三个月','Thirteen months in a bronze jar','阿佛洛狄忒回到奥林波斯，扑倒在母亲狄俄涅的膝上。','Aphrodite returns to Olympus and falls on the knees of her mother Dione, who takes her in her arms and comforts her: ''Bear it, my child; many of us who dwell on Olympus have suffered at the hands of men, and we bring hard pains on one another.'' Then she gives examples, and the first is Ares: the two sons of Aloeus, mighty Otus and Ephialtes, bound Ares in strong chains and kept him in a bronze jar for thirteen months.','claim.v0360.iliad_ares.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.4','storyver.greek.iliad_butler_ares',4,'阿波罗的召唤','Apollo''s summons','狄俄墨得斯一连三次冲向被阿波罗保护着的埃涅阿斯，第四次冲上去时，阿波罗厉声喝退了他：提丢斯的儿子，退回去，不要妄想和神平起平坐。','Three times Diomedes sprang at Aeneas, whom Apollo was shielding; the fourth time Apollo shouted at him: ''Son of Tydeus, give way, and do not think to match yourself with the gods.'' Apollo carried Aeneas to his temple in Pergamus to be healed, and then said to Ares: ''Ares, Ares, bane of men, bloodstained stormer of cities, will you not go and drive this man from the field — the son of Tydeus, who would now fight even father Zeus?','claim.v0360.iliad_ares.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.5','storyver.greek.iliad_butler_ares',5,'赫克托耳身边的神','The god beside Hector','赫克托耳从战车上跳下来，挥舞着两支长矛，在整个队伍中奔走，激起可怕的战斗。','Hector sprang from his chariot and went about among the host brandishing his two spears, rousing them to fight, and the Trojans turned and faced the Achaeans.','claim.v0360.iliad_ares.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.6','storyver.greek.iliad_butler_ares',6,'退却的希腊人','The Achaeans give ground','希腊人在阿瑞斯和赫克托耳面前既没有逃回船边，也没有挺身迎战，而是一步步地后退，因为他们知道阿瑞斯在特洛伊人中间。','Before Ares and Hector the Achaeans neither fled to their ships nor charged, but gave ground step by step, for they knew Ares was among the Trojans.','claim.v0360.iliad_ares.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.7','storyver.greek.iliad_butler_ares',7,'赫拉与雅典娜出征','Hera and Athena drive out','白臂的赫拉看见希腊人在激战中纷纷倒下，就对雅典娜说：真是糟糕，持埃癸斯盾的宙斯的孩子，我们曾向墨涅拉俄斯许诺，他一定会攻下特洛伊城平安回家，如果我们任由阿瑞斯这样发狂，这个诺言就落空了。','White-armed Hera, seeing the Achaeans perish in the fierce fighting, said to Athena: ''Alas, child of aegis-bearing Zeus, we promised Menelaus that he would sack Troy and return home safe; that promise is vain if we let Ares rage like this.','claim.v0360.iliad_ares.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.8','storyver.greek.iliad_butler_ares',8,'狄俄墨得斯的长矛','The spear of Diomedes','雅典娜找到正在擦拭伤口的狄俄墨得斯，责备他不如父亲提丢斯勇敢。','Athena found Diomedes cooling his wound and taunted him for being less bold than his father Tydeus.','claim.v0360.iliad_ares.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.9','storyver.greek.iliad_butler_ares',9,'宙斯的责备','The rebuke of Zeus','阿瑞斯飞快地来到众神居住的奥林波斯，满心痛苦地坐在宙斯身边，让父亲看他伤口里流出的神血，诉苦说：父亲宙斯，看到这种暴行你不生气吗？','Ares came swiftly to Olympus, home of the gods, sat down in pain beside Zeus, showed him the immortal blood flowing from his wound and complained: ''Father Zeus, are you not angry at such violence?','claim.v0360.iliad_ares.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.10','storyver.greek.iliad_butler_ares',10,'儿子之死','The death of his son','第十三卷里，特洛伊人得伊福玻斯向伊多墨纽斯投出长矛，没有投中，却刺中了阿瑞斯的儿子阿斯卡拉福斯的肩膀，阿斯卡拉福斯倒在尘土里，双手抓地而死。','In Book Thirteen the Trojan Deiphobus hurled his spear at Idomeneus and missed, but struck Ascalaphus, son of Ares, through the shoulder, and he fell in the dust clutching the earth.','claim.v0360.iliad_ares.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.11','storyver.greek.iliad_butler_ares',11,'众神参战','The gods go to war','第二十卷开头，阿喀琉斯重返战场，宙斯召集众神，宣布他们可以随意帮助自己喜欢的一方，免得阿喀琉斯违背命运，提前攻下特洛伊城。','At the opening of Book Twenty, as Achilles returns to battle, Zeus calls the gods together and tells them they may help whichever side they please, lest Achilles overstep fate and take Troy before its time.','claim.v0360.iliad_ares.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.12','storyver.greek.iliad_butler_ares',12,'雅典娜的石头','Athena''s stone','到了第二十一卷，众神真的动起手来。','In Book Twenty-One the gods come to blows.','claim.v0360.iliad_ares.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.greek_iliad_butler_ares.13','storyver.greek.iliad_butler_ares',13,'阿佛洛狄忒扶他离开','Aphrodite leads him away','宙斯的女儿阿佛洛狄忒拉住阿瑞斯的手，把不停呻吟、好不容易才缓过气来的他扶离战场。','Aphrodite, daughter of Zeus, took Ares by the hand and led him away, groaning continually and scarcely able to get his breath.','claim.v0360.iliad_ares.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.1','storyver.norse.skald_17_hrungnir',1,'赛马','The horse race','《诗语法》第17章讲道：索尔到东方去打巨怪了，奥丁骑着他的八足马斯莱普尼尔来到巨人国，去拜访一个名叫赫朗格尼尔的巨人。','Skáldskaparmál 17 tells: Thor had gone east to fight trolls, and Óðinn rode Sleipnir into Jötunheimr and came to a giant called Hrungnir.','claim.v0360.skald_hrungnir.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.2','storyver.norse.skald_17_hrungnir',2,'闯进阿斯加尔德','Into Ásgarðr','赫朗格尼尔骑马冲进了众神的城门，他来到大殿门口时，阿萨神族的众神邀请他进去喝酒。','Hrungnir rode in through the gods'' gate, and when he came to the hall doors the Æsir invited him in to drink.','claim.v0360.skald_hrungnir.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.3','storyver.norse.skald_17_hrungnir',3,'醉后的狂言','The drunken boasts','赫朗格尼尔喝醉了，说起了大话。','Hrungnir got drunk and began to boast.','claim.v0360.skald_hrungnir.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.4','storyver.norse.skald_17_hrungnir',4,'索尔回来','Thor returns','众神听够了他的狂言，就喊出了索尔的名字。','When the gods had had enough of his boasting they called on the name of Thor.','claim.v0360.skald_hrungnir.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.5','storyver.norse.skald_17_hrungnir',5,'黏土巨人','The clay giant','赫朗格尼尔骑马飞奔回巨人国。','Hrungnir galloped back to Jötunheimr.','claim.v0360.skald_hrungnir.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.6','storyver.norse.skald_17_hrungnir',6,'石头的心','The heart of stone','赫朗格尼尔自己的心则是出了名的：它是用坚硬的石头做的，有棱有角，是三角形的，后来人们刻的一种叫做“赫朗格尼尔之心”的符号，就是照着它的样子画的。','Hrungnir himself had a famous heart: it was made of hard stone, spiky and three-cornered, like the carved symbol that has since been called Hrungnir''s heart.','claim.v0360.skald_hrungnir.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.7','storyver.norse.skald_17_hrungnir',7,'提亚尔菲的诡计','Thjálfi''s trick','索尔带着他的仆人提亚尔菲前去决斗。','Thor went to the duel with his servant Thjálfi.','claim.v0360.skald_hrungnir.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.8','storyver.norse.skald_17_hrungnir',8,'锤与磨石','Hammer and whetstone','接着，赫朗格尼尔看见了闪电，听见了巨大的雷声，然后他看见了索尔带着神的愤怒而来。','Then Hrungnir saw lightning and heard great thunderclaps, and he saw Thor in his godly wrath.','claim.v0360.skald_hrungnir.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.9','storyver.norse.skald_17_hrungnir',9,'泥人倒下','The clay giant falls','就在索尔和赫朗格尼尔交手的同时，提亚尔菲向泥巨人默库尔卡尔菲发起了攻击。','While Thor fought Hrungnir, Thjálfi attacked the clay giant Mökkurkálfi.','claim.v0360.skald_hrungnir.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.10','storyver.norse.skald_17_hrungnir',10,'三岁的马格尼','Three-year-old Magni','提亚尔菲走到索尔身边，想把赫朗格尼尔的腿从他身上搬开，可是怎么也搬不动。','Thjálfi went to Thor and tried to lift Hrungnir''s leg off him, but could not.','claim.v0360.skald_hrungnir.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.11','storyver.norse.skald_17_hrungnir',11,'格罗亚的咒语','Gróa''s spells','索尔回到了他的家斯鲁德万加尔，可是那块磨石还嵌在他的头里。','Thor went home to Þrúðvangar, and the whetstone remained stuck in his head.','claim.v0360.skald_hrungnir.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_17_hrungnir.12','storyver.norse.skald_17_hrungnir',12,'奥尔万迪尔的脚趾','Aurvandill''s toe','索尔想让格罗亚高兴，就告诉她一个消息。','Thor wanted to make Gróa glad, so he told her some news.','claim.v0360.skald_hrungnir.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.1','storyver.egyptian.bentresh_stela_louvre_c284',1,'那哈林的贡品','Tribute in Naharin','石碑以拉美西斯二世的全套王衔开头：荷鲁斯，强壮的公牛，戴着美丽的王冠；上下埃及之王乌塞尔玛阿特拉-塞泰普恩拉，拉之子拉美西斯-美瑞阿蒙，受底比斯众神之主阿蒙-拉宠爱的人。','The stela opens with the full titulary of Ramesses II: Horus, Mighty Bull, beautiful of crowns; King of Upper and Lower Egypt Usermaatre-Setepenre, Son of Re Ramesses-Meryamun, beloved of Amun-Re, lord of the gods of Thebes.','claim.v0360.bentresh.01',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.2','storyver.egyptian.bentresh_stela_louvre_c284',2,'王后奈芙鲁拉','Queen Neferure','陛下很喜欢这位巴赫坦的公主，娶她为妻，在王衔中写下她的名字，称她为“伟大的王后奈芙鲁拉”，意思是“拉的美丽”。','His Majesty was pleased with the princess of Bakhtan and took her as his wife, writing her name in the royal titulary as Great Royal Wife Neferure, ''the beauty of Re''.','claim.v0360.bentresh.02',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.3','storyver.egyptian.bentresh_stela_louvre_c284',3,'底比斯的节日与信使','The feast at Thebes and the messenger','碑文接着说：在陛下在位的第二十三年，夏季第二个月的第二十二天，陛下正在胜利之城底比斯——众城之主——为他的父亲阿蒙-拉，两地王座之主，举行南方伊佩特的美好节日，那是阿蒙从远古以来就最喜爱的地方。','The stela goes on: in regnal year 23, second month of summer, day 22, His Majesty was in Thebes the Victorious, mistress of cities, performing the rites for his father Amun-Re, lord of the Thrones of the Two Lands, at his beautiful Feast of Southern Ipet, his favourite place since the beginning.','claim.v0360.bentresh.03',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','碑文中的年份与日期据现代学者的释读，不对应可考的史实。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.4','storyver.egyptian.bentresh_stela_louvre_c284',4,'生命之屋的书吏','The scribe of the House of Life','陛下说：把生命之屋的书吏和宫中的官员们带来。','His Majesty said: ''Bring me the scribes of the House of Life and the officials of the residence.'' They were brought to him at once.','claim.v0360.bentresh.04',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.5','storyver.egyptian.bentresh_stela_louvre_c284',5,'第二次请求','The second request','到了陛下在位的第二十六年，夏季的第一个月，陛下又在底比斯为阿蒙举行节日的时候，巴赫坦的王公再一次派使者来到陛下面前，说：我的主人陛下，请陛下派一位神来，和这个精灵作战。','In regnal year 26, first month of summer, while His Majesty was again at Thebes celebrating the feast of Amun, the prince of Bakhtan sent another messenger before His Majesty, saying: ''O sovereign, my lord, may Your Majesty send a god to fight with this spirit.'' This time the people of Bakhtan asked not for a learned man but for a god.','claim.v0360.bentresh.05',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','碑文中的年份与日期据现代学者的释读，不对应可考的史实。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.6','storyver.egyptian.bentresh_stela_louvre_c284',6,'两位孔苏','The two Khonsus','陛下来到底比斯的孔苏·奈弗尔霍特普面前，说：我的好主人，我又一次来到您面前，是为了巴赫坦王公的女儿。','His Majesty went before Khonsu-in-Thebes-Neferhotep and said: ''My good lord, I am once again before you on account of the daughter of the prince of Bakhtan.'' Then Khonsu-in-Thebes-Neferhotep was carried to Khonsu-the-Provider, the great god who expels disease demons.','claim.v0360.bentresh.06',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.7','storyver.egyptian.bentresh_stela_louvre_c284',7,'十七个月的旅程','Seventeen months on the road','陛下下令，让驱邪者孔苏登上一条大船，由五条小船护送，还配备了战车和许多马匹，从东到西护送着神前往巴赫坦。','His Majesty had Khonsu-the-Provider placed in a great bark, with five boats as escort, and chariots and many horses on the east and the west, to take the god to Bakhtan.','claim.v0360.bentresh.07',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.8','storyver.egyptian.bentresh_stela_louvre_c284',8,'公主痊愈','The princess is healed','神来到本特蕾什所在的地方，为巴赫坦王公的女儿施行了护佑。','The god went to the place where Bentresh was and made the protection over the daughter of the prince of Bakhtan, and she was well at once.','claim.v0360.bentresh.08',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.9','storyver.egyptian.bentresh_stela_louvre_c284',9,'精灵的话','The spirit speaks','那个附在公主身上的精灵，当着驱邪者孔苏的面说：欢迎你平安到来，驱赶病魔的伟大的神！','Then the spirit that was with her said before Khonsu-the-Provider: ''Welcome in peace, great god who expels disease demons!','claim.v0360.bentresh.09',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.10','storyver.egyptian.bentresh_stela_louvre_c284',10,'和精灵一起过节','A feast with the spirit','就在驱邪者孔苏和那个精灵这样交谈的时候，巴赫坦的王公和他的士兵们站在一旁，心里非常害怕。','While Khonsu-the-Provider and the spirit were speaking thus, the prince of Bakhtan stood by with his army in great fear.','claim.v0360.bentresh.10',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.11','storyver.egyptian.bentresh_stela_louvre_c284',11,'金色的鹰','The golden falcon','巴赫坦的王公在心里盘算着，说：我要让这位神留在巴赫坦，我不让他回埃及去。','The prince of Bakhtan considered in his heart, saying: ''I will make this god stay here in Bakhtan; I will not let him go to Egypt.'' So the god remained in Bakhtan three years and nine months.','claim.v0360.bentresh.11',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_bentresh_stela_louvre_c284.12','storyver.egyptian.bentresh_stela_louvre_c284',12,'回到底比斯','Return to Thebes','巴赫坦的王公让这位神启程回埃及，给了他许多各种各样的好东西作为礼物，还派了很多士兵和马匹护送。','The prince of Bakhtan let the god go to Egypt and gave him very many gifts of every good thing, with many soldiers and horses.','claim.v0360.bentresh.12',NULL,'site.egypt.karnak','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','碑文中的年份与日期据现代学者的释读，不对应可考的史实。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.1','storyver.egyptian.dorbiney_two_brothers',1,'两兄弟','The two brothers','纸草一开头说：从前有两个兄弟，同一个母亲、同一个父亲所生。','The papyrus begins: once there were two brothers of one mother and one father.','claim.v0360.two_brothers.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.2','storyver.egyptian.dorbiney_two_brothers',2,'会说话的牛','The cattle that spoke','每天早晨，巴塔赶着牛群出去，晚上再把它们赶回来，背上背着田里的各种蔬菜、牛奶、木柴和一切好东西，放在哥哥面前，哥哥和嫂子吃喝完毕，他才回到牛棚里，和牛群睡在一起。','Every morning Bata drove the cattle out and every evening brought them back, laden with all the vegetables of the field, with milk, with wood and with every good thing of the field, and laid them before his elder brother; when Anubis and his wife had eaten and drunk, Bata went to the stable and slept among his cattle.','claim.v0360.two_brothers.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.3','storyver.egyptian.dorbiney_two_brothers',3,'嫂子的诱惑','The temptation','到了耕种的季节，兄弟俩一起到田里去犁地。','At ploughing time the brothers went together to plough.','claim.v0360.two_brothers.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.4','storyver.egyptian.dorbiney_two_brothers',4,'谎言','The lie','巴塔走后，嫂子害怕自己说的话被传出去。','When Bata had gone, his brother''s wife was afraid of what she had said.','claim.v0360.two_brothers.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.5','storyver.egyptian.dorbiney_two_brothers',5,'母牛的警告','The cows'' warning','哥哥一听，就像上埃及的豹子一样暴怒。','Hearing this, the elder brother became like an Upper Egyptian leopard.','claim.v0360.two_brothers.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.6','storyver.egyptian.dorbiney_two_brothers',6,'鳄鱼之河','The water full of crocodiles','巴塔一边逃跑，一边向太阳神拉-哈拉赫提祈祷，说：我的好主人，您是分辨恶人和义人的神。','As he fled, Bata prayed to Pre-Harakhti, saying: ''My good lord, it is you who judge the wrongdoer from the just.'' And Re heard all his plea.','claim.v0360.two_brothers.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.7','storyver.egyptian.dorbiney_two_brothers',7,'黎明时的真相','The truth at dawn','天亮了，太阳升起来，两兄弟隔着河相望。','When the land grew light and the sun rose, the brothers looked at each other across the water.','claim.v0360.two_brothers.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.8','storyver.egyptian.dorbiney_two_brothers',8,'松树谷的心','The heart in the Valley of the Pine','巴塔对哥哥说：你只记得坏事，就不能记得一件好事，或者我为你做过的一件事吗？','Bata said to his elder brother: ''You remember one bad thing; can you not remember one good thing, or a thing I did for you?','claim.v0360.two_brothers.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.9','storyver.egyptian.dorbiney_two_brothers',9,'九神与克努姆','The Ennead and Khnum','巴塔在松树谷里独自生活，白天打猎，晚上回到松树下睡觉，他的心就放在松树的花顶上。','Bata lived alone in the Valley of the Pine, hunting desert game by day and coming back at evening to sleep under the pine on whose flower his heart lay.','claim.v0360.two_brothers.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.10','storyver.egyptian.dorbiney_two_brothers',10,'大海与一缕头发','The sea and a lock of hair','巴塔深深地爱着她。','Bata loved her very much.','claim.v0360.two_brothers.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.11','storyver.egyptian.dorbiney_two_brothers',11,'法老的使者','Pharaoh''s envoys','法老召来了精通学问的书吏，他们对法老说：这缕头发属于拉-哈拉赫提的一个女儿，所有神的精华都在她身上，这是从另一个国度给您的礼物。','Pharaoh summoned the learned scribes, who said to him: ''This lock of hair belongs to a daughter of Pre-Harakhti, in whom is the fluid of every god; it is a greeting to you from another land.','claim.v0360.two_brothers.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.12','storyver.egyptian.dorbiney_two_brothers',12,'砍倒松树','The pine is cut down','法老问她关于她丈夫的事，她对法老说：让人去砍倒那棵松树，把它砍成碎片。','Pharaoh asked her about her husband, and she said to Pharaoh: ''Let the pine be felled and cut to pieces.'' So Pharaoh sent soldiers with their tools to fell the pine.','claim.v0360.two_brothers.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.13','storyver.egyptian.dorbiney_two_brothers',13,'起沫的啤酒','The frothing beer','就在松树被砍倒的第二天，巴塔的哥哥阿努比斯走进家里，坐下洗手，有人递给他一罐啤酒，啤酒起了泡沫；又递给他一罐葡萄酒，葡萄酒也变浑浊了。','On the day after the pine was felled, Anubis, Bata''s elder brother, entered his house and sat down to wash his hands; he was given a jug of beer, and it fermented; he was given another of wine, and it turned bad.','claim.v0360.two_brothers.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.14','storyver.egyptian.dorbiney_two_brothers',14,'公牛','The bull','巴塔对哥哥说：看，我要变成一头公牛，身上有各种美丽的颜色，没有人知道它的来历。','Bata said to his elder brother: ''See, I shall become a great bull of every beautiful colour, whose nature no one will know.','claim.v0360.two_brothers.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_dorbiney_two_brothers.15','storyver.egyptian.dorbiney_two_brothers',15,'两棵鳄梨树与新国王','The persea trees and the new king','公牛被宰杀时，它的两滴血落在法老宫殿门口的两根门柱旁，长成了两棵高大的鳄梨树，每一棵都美极了。','When the bull was slaughtered, two drops of its blood fell beside the two doorposts of Pharaoh''s palace and grew into two great persea trees, each of them very beautiful.','claim.v0360.two_brothers.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.1','storyver.egyptian.deir_el_bahari_birth_cycle',1,'众神的会议','The council of the gods','浮雕的第一幕画的是众神之王阿蒙-拉坐在宝座上，面前是底比斯和赫利奥波利斯的众神。','The first scene shows Amun-Re, king of the gods, enthroned before the gods of Thebes and Heliopolis.','claim.v0360.hatshepsut_birth.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.2','storyver.egyptian.deir_el_bahari_birth_cycle',2,'阿蒙与托特','Amun and Thoth','下一幕里，阿蒙与智慧之神托特交谈。','In the next scene Amun speaks with Thoth, god of wisdom, scribe and messenger of the gods, shown with the head of an ibis.','claim.v0360.hatshepsut_birth.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.3','storyver.egyptian.deir_el_bahari_birth_cycle',3,'托特引路','Thoth leads the way','第三幕画的是托特在前面领路，阿蒙跟在后面，一起前往王后雅赫摩斯所在的王宫。','The third scene shows Thoth leading the way and Amun following, going together to the palace where Queen Ahmose is.','claim.v0360.hatshepsut_birth.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.4','storyver.egyptian.deir_el_bahari_birth_cycle',4,'王后的寝宫','In the queen''s chamber','阿蒙化作王后的丈夫图特摩斯一世的模样，来到雅赫摩斯的寝宫。','Amun came to Ahmose''s chamber in the form of her husband, Thutmose I.','claim.v0360.hatshepsut_birth.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.5','storyver.egyptian.deir_el_bahari_birth_cycle',5,'阿蒙的吩咐','Amun''s command','阿蒙离开王后以后，来到陶工之神克努姆面前，吩咐他塑造将要出生的孩子。','Leaving the queen, Amun came to Khnum, the potter god, and commanded him to fashion the child to be born.','claim.v0360.hatshepsut_birth.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.6','storyver.egyptian.deir_el_bahari_birth_cycle',6,'陶轮上的孩子','The child on the potter''s wheel','这一幕是整组浮雕中最著名的画面之一：羊头的克努姆坐在陶轮前，陶轮上站着两个一模一样的小孩，一个是哈特谢普苏特的身体，一个是她的卡。','This is one of the most famous scenes of the cycle: ram-headed Khnum sits at his potter''s wheel, on which stand two identical small children — Hatshepsut''s body and her ka.','claim.v0360.hatshepsut_birth.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.7','storyver.egyptian.deir_el_bahari_birth_cycle',7,'托特的报喜','Thoth''s announcement','孩子在陶轮上塑造完成以后，托特又一次出场。','When the child had been shaped on the wheel, Thoth appeared again — this time before Queen Ahmose, to announce the birth to her.','claim.v0360.hatshepsut_birth.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.8','storyver.egyptian.deir_el_bahari_birth_cycle',8,'走向产房','To the birth chamber','接下来，克努姆和赫凯特一左一右，牵着王后雅赫摩斯的手，领她走向产房。','Next Khnum and Heqet, one on each side, take Queen Ahmose by the hands and lead her to the birth chamber.','claim.v0360.hatshepsut_birth.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.9','storyver.egyptian.deir_el_bahari_birth_cycle',9,'诞生','The birth','诞生的一幕画得庄严而拥挤：王后雅赫摩斯坐在宝座上，抱着刚出生的婴儿，四周围绕着许多神灵和精灵，它们分成几排，有的跪着，有的举着手表示欢呼。','The birth scene is solemn and crowded: Queen Ahmose sits enthroned holding the newborn child, surrounded by many gods and spirits in rows, some kneeling, some raising their hands in acclaim.','claim.v0360.hatshepsut_birth.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','诞生一幕残缺较多，部分神灵的身份学者意见不一。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.10','storyver.egyptian.deir_el_bahari_birth_cycle',10,'献给阿蒙','Presented to Amun','孩子出生以后，女神哈托尔把她抱到阿蒙面前。','After the birth the goddess Hathor carried the child to Amun.','claim.v0360.hatshepsut_birth.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.11','storyver.egyptian.deir_el_bahari_birth_cycle',11,'神的哺育','The divine nursing','接下来，阿蒙吩咐众女神哺育这个孩子。','Next Amun commands the goddesses to nurse the child.','claim.v0360.hatshepsut_birth.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_deir_el_bahari_birth_cycle.12','storyver.egyptian.deir_el_bahari_birth_cycle',12,'托特呈子与神定寿命','Thoth presents the child, and the gods fix her lifetime','在诞生浮雕的最后几幕，托特把孩子和她的卡一起呈到阿蒙面前（学者布鲁纳编为第十四幕）。','In the last scenes of the cycle Thoth presents the child and her ka together to Amun (Brunner''s scene 14).','claim.v0360.hatshepsut_birth.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.1','storyver.egyptian.shabaka_stone_memphite',1,'被虫蛀的古书','The worm-eaten book','石板最上面的两行横写的文字，是沙巴卡国王的王衔和一段说明：上下埃及之王沙巴卡，受“城墙之南的普塔”喜爱的人，愿他像拉一样永远活着。','The two horizontal lines at the top of the slab give King Shabaka''s titles and a statement: the King of Upper and Lower Egypt Shabaka, beloved of Ptah-South-of-his-Wall, living like Re for ever.','claim.v0360.memphite.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.2','storyver.egyptian.shabaka_stone_memphite',2,'塔特恩','Ta-tenen','序言之后，碑文称颂普塔：上下埃及之王就是这个伟大的名字——塔特恩，城墙之南，永恒之主。','After the preface the text praises Ptah: the King of Upper and Lower Egypt is this Great Name, Ta-tenen, South-of-his-Wall, Lord of Eternity.','claim.v0360.memphite.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.3','storyver.egyptian.shabaka_stone_memphite',3,'盖布的第一次裁决','Geb''s first judgement','碑文接着讲了一个关于王权的故事。','Next the text tells a story of kingship.','claim.v0360.memphite.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.4','storyver.egyptian.shabaka_stone_memphite',4,'全部遗产归于荷鲁斯','The whole inheritance to Horus','可是后来，盖布觉得荷鲁斯的份额和塞特的份额一样，这样不对。','But then it seemed wrong to Geb that the portion of Horus was like the portion of Seth.','claim.v0360.memphite.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.5','storyver.egyptian.shabaka_stone_memphite',5,'芦苇与纸草','Reed and papyrus','碑文接着说：芦苇和纸草被放在普塔神庙的双扇大门上。','The text goes on: reed and papyrus were placed on the double door of the house of Ptah.','claim.v0360.memphite.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','此段之后石板有大段文字因被用作磨盘而磨损，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.6','storyver.egyptian.shabaka_stone_memphite',6,'普塔的诸形','The forms of Ptah','在磨损的部分之后，碑文进入了最著名的“神学”部分。','After the worn section the text enters its most famous part, the ''theology''.','claim.v0360.memphite.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.7','storyver.egyptian.shabaka_stone_memphite',7,'心与舌','Heart and tongue','碑文接着说：在心中成形的，在舌上成形的，是阿图姆的形象。','The text goes on: there took shape in the heart, there took shape on the tongue the form of Atum.','claim.v0360.memphite.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.8','storyver.egyptian.shabaka_stone_memphite',8,'牙齿与嘴唇','Teeth and lips','碑文接着把普塔的九柱神和阿图姆的九柱神作了对比：普塔的九柱神在他面前，是心与舌、牙齿与嘴唇。','The text then compares Ptah''s Ennead with Atum''s: his Ennead is before him as heart and tongue, teeth and lips.','claim.v0360.memphite.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.9','storyver.egyptian.shabaka_stone_memphite',9,'心想与舌说','What the heart devises and the tongue commands','碑文接着解释这种创造是怎样发生的：眼睛的看见，耳朵的听见，鼻子的呼吸，都报告给心。','The text then explains how this creation works: the sight of the eyes, the hearing of the ears, the breathing of the nose report to the heart.','claim.v0360.memphite.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.10','storyver.egyptian.shabaka_stone_memphite',10,'普塔歇息','Ptah rests','碑文说：所以人们说普塔是“创造一切、生出众神的那一位”。','The text says: so it is said of Ptah, ''He who made all and created the gods.'' He is Ta-tenen, who gave birth to the gods, and from whom every thing came forth — foods, provisions, divine offerings, all good things.','claim.v0360.memphite.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.11','storyver.egyptian.shabaka_stone_memphite',11,'众神进入他们的身体','The gods enter their bodies','碑文接着说：他生出了众神，他建造了城市，他设立了各州，他把众神安置在他们的神龛里，他确定了他们的祭品，他建立了他们的神殿，他按照他们的心愿做出了他们的身体。','The text goes on: he gave birth to the gods, he made the towns, he established the nomes, he placed the gods in their shrines, he settled their offerings, he established their shrines, he made their bodies according to their wishes.','claim.v0360.memphite.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.egyptian_shabaka_stone_memphite.12','storyver.egyptian.shabaka_stone_memphite',12,'孟菲斯的奥西里斯','Osiris at Memphis','碑文的最后一部分回到了奥西里斯的故事。','The last part of the text returns to Osiris.','claim.v0360.memphite.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.1','storyver.ugaritic.ktu_1_3_1_4_palace',1,'巴力的宴会','Baal''s feast','KTU 1.3 第一栏开头，风暴之神强大的巴力坐在宴席上。','At the opening of KTU 1.3, column I, Mightiest Baal the storm god sits at a feast.','claim.v0360.baal_palace.01',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.2','storyver.ugaritic.ktu_1_3_1_4_palace',2,'阿娜特的战斗','Anat''s battle','第二栏讲巴力的妹妹、少女阿娜特。','Column II tells of Baal''s sister, the maiden Anat.','claim.v0360.baal_palace.02',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.3','storyver.ugaritic.ktu_1_3_1_4_palace',3,'巴力的口信','Baal''s message','第三栏里，巴力派他的两个使者古帕努和乌加尔去找阿娜特。','In column III Baal sends his two messengers, Gupn and Ugar, to Anat.','claim.v0360.baal_palace.03',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.4','storyver.ugaritic.ktu_1_3_1_4_palace',4,'阿娜特的惊恐','Anat''s alarm','阿娜特看见两位使者走来，双脚发抖，腰部打颤，脸上流汗。','When Anat saw the two messengers coming, her feet shook, her loins trembled, her face sweated.','claim.v0360.baal_palace.04',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.5','storyver.ugaritic.ktu_1_3_1_4_palace',5,'巴力没有房子','Baal has no house','在萨方山上，巴力向阿娜特说出了他的苦恼：巴力没有像众神那样的房子，没有像阿西拉特的儿子们那样的庭院。','On Saphon Baal tells Anat his grief: Baal has no house like the gods, no court like the sons of Athirat.','claim.v0360.baal_palace.05',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.6','storyver.ugaritic.ktu_1_3_1_4_palace',6,'寻找工匠','Sending for the craftsman','第六栏里，一位使者被派去寻找工匠之神科塔尔-瓦-哈西斯，意思是“灵巧而聪慧的神”。','In column VI a messenger is sent to find the craftsman god Kothar-wa-Khasis, ''Skilful-and-Wise''.','claim.v0360.baal_palace.06',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.7','storyver.ugaritic.ktu_1_3_1_4_palace',7,'给阿西拉特的礼物','Gifts for Athirat','KTU 1.4 第一栏又一次重复了巴力的哀叹：巴力没有像众神那样的房子，没有像阿西拉特的儿子们那样的庭院。','Column I of KTU 1.4 repeats Baal''s lament: Baal has no house like the gods, no court like the sons of Athirat.','claim.v0360.baal_palace.07',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.8','storyver.ugaritic.ktu_1_3_1_4_palace',8,'海边的女神','The goddess by the sea','第二栏里，众神之母阿西拉特正在海边。','In column II Athirat, mother of the gods, is by the sea.','claim.v0360.baal_palace.08',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.9','storyver.ugaritic.ktu_1_3_1_4_palace',9,'阿西拉特的疑问','Athirat''s question','第三栏开头残缺，接着是巴力向众神抱怨自己在众神的集会上受到了侮辱：他站起来，说有人在众神的集会上对他吐唾沫。','Column III opens broken; then Baal complains that he was insulted in the assembly of the gods: he stood and said someone spat upon him in the gathering of the gods.','claim.v0360.baal_palace.09',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.10','storyver.ugaritic.ktu_1_3_1_4_palace',10,'骑驴见伊勒','Riding to El','第四栏里，阿西拉特吩咐她的仆人、渔夫库德什-瓦-阿姆鲁尔：给驴套上鞍子，给驴装上银子的缰绳，金子的鞍具，为我的母驴备好鞍子。','In column IV Athirat bids her servant, the fisherman Qodesh-wa-Amrur: saddle the donkey, harness the ass, put on the trappings of silver, the gear of gold, make ready my she-ass.','claim.v0360.baal_palace.10',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.11','storyver.ugaritic.ktu_1_3_1_4_palace',11,'伊勒的允许','El''s consent','阿西拉特回答伊勒说：伊勒啊，你的命令是英明的，你的智慧与永恒同在，你的命令带来幸运的生活。','Athirat answers El: your decree, El, is wise, your wisdom is with eternity, your command brings a fortunate life.','claim.v0360.baal_palace.11',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.12','storyver.ugaritic.ktu_1_3_1_4_palace',12,'窗户之争','The dispute over the window','阿娜特高兴得跳了起来，奔向萨方山，对巴力说：好消息，巴力！','Anat leaps for joy and speeds to Saphon, telling Baal: good news, Baal!','claim.v0360.baal_palace.12',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.13','storyver.ugaritic.ktu_1_3_1_4_palace',13,'火中成屋','The house made in fire','第六栏接着讲房子的建造。','Column VI goes on with the building.','claim.v0360.baal_palace.13',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.ugaritic_ktu_1_3_1_4_palace.14','storyver.ugaritic.ktu_1_3_1_4_palace',14,'开窗与雷声','The window and the thunder','第七栏里，巴力离开宫殿，从一座城走到另一座城，从一个镇走到另一个镇，夺取了六十六座城、七十七个镇。','In column VII Baal leaves the palace and goes from city to city, town to town, seizing sixty-six cities, seventy-seven towns.','claim.v0360.baal_palace.14',NULL,'site.syria.ugarit','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','泥板此处有残缺，栏次划分与断句据现代学者的整理，残缺处不补写。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.1','storyver.sumerian.inana_ebih_etcsl',1,'可怖的女神','The goddess of terror','诗歌以对伊南娜的赞美开始：她是掌握可怕神力的女神，身披恐怖，骑在伟大的神力之上。','The poem opens in praise of Inana: goddess of the fearsome divine powers, clad in terror, riding on the great divine powers.','claim.v0360.inana_ebih.01',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.2','storyver.sumerian.inana_ebih_etcsl',2,'天地间的狮吼','A lion''s roar in heaven and on earth','颂歌继续赞美伊南娜：在天上和地上，你像狮子一样吼叫，把人们打倒；你像一头巨大的野牛，在敌对的国度中奔驰；你像一头狮子，用毒液让敌人和反叛者倒下。','The hymn goes on: in heaven and on earth you roar like a lion and strike people down; like a huge wild bull you rush through hostile lands; like a lion you make enemies and rebels fall with your venom.','claim.v0360.inana_ebih.02',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.3','storyver.sumerian.inana_ebih_etcsl',3,'不肯低头的山','The mountain that would not bow','接着，伊南娜自己开口说话：我，女神，在天上巡行，在地上巡行；我，伊南娜，在天上巡行，在地上巡行，在埃拉姆和苏巴尔图巡行，在卢卢布山区巡行。','Then Inana herself speaks: I, the goddess, was walking around in heaven, walking around on earth; I, Inana, was walking around in heaven and on earth, in Elam and Subir, in the Lulubi mountains.','claim.v0360.inana_ebih.03',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.4','storyver.sumerian.inana_ebih_etcsl',4,'伊南娜的誓言','Inana''s vow','伊南娜接着发誓：我要让恐怖充满这座高耸的山脉。','Inana goes on to vow: I shall fill the soaring mountain range with my terror.','claim.v0360.inana_ebih.04',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.5','storyver.sumerian.inana_ebih_etcsl',5,'盛装出发','Arrayed for the journey','月神苏恩的女儿伊南娜穿上了她的衣服，披上了王后的服饰，让喜悦笼罩全身。','Inana, daughter of Suen, put on her garments, the garments of queenship, and wrapped herself in joy.','claim.v0360.inana_ebih.05',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.6','storyver.sumerian.inana_ebih_etcsl',6,'向父亲安致敬','Before her father An','伊南娜来到天神安的面前，在他面前俯伏下拜，然后对他说：我的父亲安，我向你致敬！','Inana came before An, the sky god, prostrated herself before him and said: My father An, I greet you!','claim.v0360.inana_ebih.06',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.7','storyver.sumerian.inana_ebih_etcsl',7,'安的警告','An''s warning','众神之王安回答她说：我的小女儿要求毁灭那座山——她要去做什么？','An, king of the gods, answered her: my little one demands the mountain''s destruction — what is she taking on?','claim.v0360.inana_ebih.07',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.8','storyver.sumerian.inana_ebih_etcsl',8,'打开武库','The arsenal thrown open','安这样说完，女主人伊南娜在愤怒和狂怒之中，打开了战斗之屋的大门，推开了青金石的城门。','When An had spoken, the lady, in her rage and anger, opened the gate of the house of battle and pushed open the lapis lazuli door.','claim.v0360.inana_ebih.08',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.9','storyver.sumerian.inana_ebih_etcsl',9,'山的毁灭','The destruction of the mountain','伊南娜抓住了埃比赫的脖子，像割下一把草一样；她把匕首的利齿刺进它的内部，像雷声一样吼叫。','Inana seized Ebiḫ by the neck as one cuts grass; she pressed the teeth of the dagger into its interior and roared like thunder.','claim.v0360.inana_ebih.09',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.sumerian_inana_ebih_etcsl.10','storyver.sumerian.inana_ebih_etcsl',10,'胜利的宣言','The victory speech','伊南娜站在被毁灭的山上，宣告她的胜利：山脉啊，因为你高耸，因为你巍峨，因为你迷人，因为你美丽，因为你穿着神圣的衣服，因为你伸向天空，因为你没有把鼻子贴到地上，因为你没有用嘴唇亲吻尘土，所以我杀死了你，让你倒下。','Standing on the ruined mountain, Inana proclaims her victory: Mountain range, because of your elevation, because of your height, because of your attractiveness, because of your beauty, because you wore a holy garment, because you reached up to heaven, because you did not put your nose to the ground, because you did not rub your lips in the dust, I have killed you and brought you low.','claim.v0360.inana_ebih.10',NULL,'place.sumerian.ebih','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','本篇按段落定位，不标具体行号；个别诗行残缺或意义不明。','2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.1','storyver.chinese.lunheng_leixu',1,'盛夏的雷电','Summer thunder','王充在《雷虚》的开头写道：盛夏的时候，雷电来得又快又猛，劈断树木，毁坏房屋，有时还会打死人。','Wang Chong opens ''Lei Xu'' thus: in high summer thunder and lightning come swift and fierce, splitting trees, wrecking houses and sometimes killing people.','claim.v0360.leigong_leixu.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.2','storyver.chinese.lunheng_leixu',2,'天怒之说','Heaven''s anger','王充首先反驳“雷是天怒”的说法。','Wang first refutes the idea that thunder is Heaven''s anger.','claim.v0360.leigong_leixu.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.3','storyver.chinese.lunheng_leixu',3,'取龙与罚过','Taking dragons and punishing faults','王充在《雷虚》中反复回到同一个问题：雷击中的人和物，究竟是被上天特意选中的，还是偶然碰上的？','In ''Lei Xu'' Wang returns again and again to one question: are the people and things struck by thunder chosen by Heaven, or simply in the way?','claim.v0360.leigong_leixu.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.4','storyver.chinese.lunheng_leixu',4,'画中的雷公','Leigong in the paintings','王充接着描述了汉代画工所画的雷的样子：画工们画雷的形状，是一面接一面串在一起的鼓，像一串连鼓；又画一个人，有着力士一样的容貌，称他为雷公，让他左手拉着连鼓，右手举着槌子，像是正在敲打的样子。','Wang then describes how Han painters drew thunder: painters picture thunder as drums strung together one after another, like a chain of linked drums; and they draw a man with the look of a strongman, whom they call Leigong, the Thunder Lord, making him pull the linked drums with his left hand and raise a mallet in his right, as if striking.','claim.v0360.leigong_leixu.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.5','storyver.chinese.lunheng_leixu',5,'雷公怎样飞','How could Leigong fly?','王充对画中的雷公提出了好几条质疑。','Wang raises several objections to the painted Leigong.','claim.v0360.leigong_leixu.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.6','storyver.chinese.lunheng_leixu',6,'雷是火','Thunder is fire','王充提出了自己的看法：雷，是火。','Wang states his own view: thunder is fire.','claim.v0360.leigong_leixu.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.7','storyver.chinese.lunheng_leixu',7,'炉中的水','Water on the furnace','王充又用一个日常的经验来说明雷的威力：拿一斗水浇进冶炼铸造的炉火里，水气激荡，迸裂开来，发出的声音就像雷一样；如果有人靠得太近，一定会被灼伤身体。','Wang also uses an everyday experience to show thunder''s force: pour a peck of water onto the fire of a smelting furnace, and the steam bursts and cracks with a sound like thunder; anyone too close will surely be scorched.','claim.v0360.leigong_leixu.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.chinese_lunheng_leixu.8','storyver.chinese.lunheng_leixu',8,'太阳的激气','The surging energy of great yang','在《雷虚》的结论部分，王充说：雷是太阳之气激发出来的。','In the conclusion of ''Lei Xu'' Wang says: thunder is the surging energy of great yang.','claim.v0360.leigong_leixu.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.1','storyver.norse.gylf_4_12_creation_long',1,'尼夫尔海姆','Niflheim','瑞典国王古鲁菲来到阿斯加尔德，向坐在三个高座上的“至高者”“同样高者”和“第三者”提问。','King Gylfi of Sweden came to Ásgarðr and put his questions to the three seated on high thrones — High, Just-as-high and Third.','claim.v0360.gylf_creation.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.2','storyver.norse.gylf_4_12_creation_long',2,'穆斯佩尔与苏尔特','Muspell and Surtr','第三者接着说：最先存在的，是南方的一个世界，叫做穆斯佩尔。','Third went on: first of all there was a world in the southern region called Muspell.','claim.v0360.gylf_creation.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.3','storyver.norse.gylf_4_12_creation_long',3,'金伦加鸿沟','Ginnungagap','古鲁菲问：在人类出现以前，世界是什么样子？','Gylfi asked how things were before generations of men came to be.','claim.v0360.gylf_creation.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.4','storyver.norse.gylf_4_12_creation_long',4,'尤弥尔','Ymir','至高者接着说：融化的霜滴在热力的作用下有了生命，变成了一个人的形状，他名叫尤弥尔，霜巨人们叫他奥尔格尔米尔，所有的霜巨人都是他的后代。','High went on: when the drops of melting rime were quickened by the power of the heat, they took the shape of a man, who is called Ymir; the frost-giants call him Aurgelmir, and from him are descended all the families of frost-giants.','claim.v0360.gylf_creation.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.5','storyver.norse.gylf_4_12_creation_long',5,'母牛与布里','The cow and Búri','古鲁菲问：尤弥尔住在哪里，靠什么活着？','Gylfi asked where Ymir lived and what he lived on.','claim.v0360.gylf_creation.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.6','storyver.norse.gylf_4_12_creation_long',6,'博尔与贝斯特拉','Borr and Bestla','至高者接着说：布里有了一个儿子，名叫博尔。','High went on: Búri begot a son called Borr.','claim.v0360.gylf_creation.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.7','storyver.norse.gylf_4_12_creation_long',7,'杀死尤弥尔','The slaying of Ymir','古鲁菲问：他们之间是和睦相处，还是互相敌对？','Gylfi asked whether there was peace between them or not.','claim.v0360.gylf_creation.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.8','storyver.norse.gylf_4_12_creation_long',8,'大地与海','Earth and sea','古鲁菲问：如果你们认为博尔的儿子们是神，那他们后来做了什么？','Gylfi asked what the sons of Borr did then, if they are to be believed gods.','claim.v0360.gylf_creation.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.9','storyver.norse.gylf_4_12_creation_long',9,'天空与群星','Sky and stars','第三者说：他们又拿起尤弥尔的头骨，用它造成天空，把它架在大地的上方，四个角各让一个矮人撑着，这四个矮人的名字是奥斯特里、韦斯特里、诺尔德里和苏德里——东、西、北、南。','Third said: they also took his skull and made the sky from it, set it up over the earth with four points, and under each corner put a dwarf, named Austri, Vestri, Norðri and Suðri — East, West, North and South.','claim.v0360.gylf_creation.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.10','storyver.norse.gylf_4_12_creation_long',10,'米德加尔德','Miðgarðr','至高者说：大地是圆的，四周环绕着深深的海洋。','High said: the earth is circular, and around it lies the deep sea.','claim.v0360.gylf_creation.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.11','storyver.norse.gylf_4_12_creation_long',11,'最初的人与奥丁的家','The first people and Odin''s household','同样高者说：博尔的儿子们沿着海岸走，发现了两根树干，就拿起它们，用它们造出了人。','Just-as-high said: as the sons of Borr walked along the shore they found two logs and picked them up and made people of them.','claim.v0360.gylf_creation.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.12','storyver.norse.gylf_4_12_creation_long',12,'夜与昼','Night and Day','同样高者接着说：住在巨人国的一个巨人名叫纳尔菲，他有一个女儿叫夜，诺特。','Just-as-high went on: there was a giant living in Jötunheimr called Nörfi or Narfi.','claim.v0360.gylf_creation.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','《欺骗古鲁菲》第9章称约尔德为奥丁之女，第10章称她为夜与安纳尔之女，两说并存。','2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.13','storyver.norse.gylf_4_12_creation_long',13,'太阳与月亮','Sun and Moon','古鲁菲问：太阳和月亮是怎样运行的？','Gylfi asked how the sun and moon are steered.','claim.v0360.gylf_creation.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_gylf_4_12_creation_long.14','storyver.norse.gylf_4_12_creation_long',14,'追逐日月的狼','The wolves that chase sun and moon','古鲁菲说：太阳跑得飞快，好像害怕什么，就算她怕死，也不会跑得更快了。','Gylfi said: the sun moves fast, almost as if she were afraid; she could not go faster if she feared for her life.','claim.v0360.gylf_creation.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.1','storyver.norse.skald_35_sif_long',1,'希芙与乌勒尔','Sif and Ullr','在斯诺里的《欺骗古鲁菲》里，至高者向古鲁菲一一介绍阿萨神族的众神。','In Snorri''s Gylfaginning, High tells Gylfi about each of the Æsir.','claim.v0360.skald_sif.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.2','storyver.norse.skald_35_sif_long',2,'被剪掉的金发','The shorn hair','《诗语法》第35章从一个问题开始：为什么金子被称为“希芙的头发”？','Skáldskaparmál 35 begins with a question: why is gold called Sif''s hair?','claim.v0360.skald_sif.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.3','storyver.norse.skald_35_sif_long',3,'索尔的愤怒','Thor''s anger','索尔发现妻子的头发被剪光后，立刻抓住了洛基。','When Thor found his wife''s hair shorn, he seized Loki and would have broken every bone in his body.','claim.v0360.skald_sif.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.4','storyver.norse.skald_35_sif_long',4,'伊瓦尔迪的儿子们','The sons of Ívaldi','洛基于是去找那些被称为伊瓦尔迪之子的矮人。','So Loki went to the dwarves called the sons of Ívaldi.','claim.v0360.skald_sif.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.5','storyver.norse.skald_35_sif_long',5,'洛基的赌注','Loki''s wager','洛基拿着宝物，找到一个名叫勃洛克的矮人，跟他打赌，把自己的头押上：他说勃洛克的兄弟埃特里——有些抄本和后人叫他辛德里——不可能打造出三件和这三件一样好的宝物。','Loki took the treasures and wagered his head with a dwarf called Brokkr that his brother Eitri — called Sindri in some manuscripts and later writers — could not make three treasures as good as these.','claim.v0360.skald_sif.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.6','storyver.norse.skald_35_sif_long',6,'金鬃野猪','The golden-bristled boar','埃特里把一张猪皮放进炉子里，吩咐勃洛克拉风箱，在他把东西从炉子里取出来以前，一刻也不许停下。','Eitri laid a pigskin in the forge and told Brokkr to blow the bellows and not stop until he took out what he had put in.','claim.v0360.skald_sif.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.7','storyver.norse.skald_35_sif_long',7,'指环德劳普尼尔','The ring Draupnir','接着，埃特里把金子放进炉子里，又吩咐勃洛克拉风箱，在他回来以前不许停下。','Next Eitri laid gold in the forge and bade Brokkr blow and not stop until he came back.','claim.v0360.skald_sif.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.8','storyver.norse.skald_35_sif_long',8,'锤子与苍蝇','The hammer and the fly','最后，埃特里把铁放进炉子里，对勃洛克说，必须一直拉风箱，否则一切都会毁掉。','Last, Eitri laid iron in the forge and told Brokkr he must keep blowing or everything would be spoiled.','claim.v0360.skald_sif.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.9','storyver.norse.skald_35_sif_long',9,'三位裁判','The three judges','勃洛克带着他的宝物来到阿斯加尔德，洛基也带来了伊瓦尔迪之子的宝物。','Brokkr came to Ásgarðr with his treasures, and Loki brought the treasures of the sons of Ívaldi.','claim.v0360.skald_sif.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.10','storyver.norse.skald_35_sif_long',10,'洛基的礼物','Loki''s gifts','洛基先献上他的宝物。','Loki presented his treasures first.','claim.v0360.skald_sif.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.11','storyver.norse.skald_35_sif_long',11,'勃洛克的礼物与判决','Brokkr''s gifts and the verdict','接着，勃洛克献上他的宝物。','Then Brokkr presented his treasures.','claim.v0360.skald_sif.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z'),
('storyevent.v0360.norse_skald_35_sif_long.12','storyver.norse.skald_35_sif_long',12,'缝上的嘴','The sewn lips','洛基提出要用钱赎回自己的头，可矮人说没有这回事。','Loki offered to redeem his head, but the dwarf said there was no hope of that.','claim.v0360.skald_sif.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T22:00:00Z');

