UPDATE stories SET editorial_note='原创中文概述；不复制现代译文，不把后世版本并入本见证。v0.36 起作为“荷马颂歌连载”的第一部，长篇版本依据《荷马颂歌·致得墨忒耳》全篇。',updated_at='2026-10-24T22:00:00Z' WHERE id='story.greek.demeter_persephone';
UPDATE stories SET editorial_note='长篇版本依据斯诺里《埃达·诗语法》第35章逐段讲述希芙的金发与六件宝物的来历，开头关于乌勒尔的一章据《欺骗古鲁菲》第31章；原有的三段概述版本保留。锻造矮人在《诗语法》中称埃特里，有些抄本与后人作辛德里，名称异文仍独立记录。',updated_at='2026-10-24T22:00:00Z' WHERE id='story.norse.forging_treasures';
UPDATE stories SET editorial_note='长篇版本依据斯诺里《埃达·欺骗古鲁菲》第4–12章逐章讲述，包括布里、博尔、约尔德与日月的来历；原有的第5–8章概述版本保留。《女巫的预言》等诗歌见证另行对读，不并入。',updated_at='2026-10-24T22:00:00Z' WHERE id='story.norse.ymir_world';



